#!/usr/bin/env python3
"""Generates the per-mode maps (symmetric layouts are mirrored so both teams get the same map).
The maps are a build artifact: CMake runs this (python3, nothing else needed) and writes them to maps/, which
.gitignore leaves out. Edit this file and rebuild; never hand-edit the .qmap files it writes.
  python3 tools/make_maps.py [--out DIR]   writes every map (default: maps/ next to tools/)
  python3 tools/make_maps.py --list        prints the names of the maps it makes, writes nothing
Output is byte-for-byte deterministic (seeded generators only; LF line endings on every platform)."""
import os, random, math, argparse, contextlib
from collections import Counter
_ap = argparse.ArgumentParser(description="generate the shipped maps")
_ap.add_argument("--out", default=os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "maps"))
_ap.add_argument("--list", action="store_true", help="print the map names instead of writing the maps")
ARGS = _ap.parse_args()
OUT = ARGS.out
MADE = []

class M:
    def __init__(s, title, mode, sun=(0.45, 1.0, 0.3)):
        s.lines = [f"# generated by tools/make_maps.py", f"title {title}", f"for {mode}" if mode else "# every mode, none in particular", "sun %g %g %g" % sun]
    def box(s, x0, y0, z0, x1, y1, z1, accent=False, mirror=False, mat=None):
        kw = mat or ('accent' if accent else 'box')   # mat: box / accent / metal / glow
        s.lines.append(f"{kw} {x0:g} {y0:g} {z0:g} {x1:g} {y1:g} {z1:g}")
        if mirror: s.lines.append(f"{kw} {-x1:g} {y0:g} {-z1:g} {-x0:g} {y1:g} {-z0:g}")
    def metal(s, *a, **k): s.box(*a, mat="metal", **k)
    def glow(s, *a, **k): s.box(*a, mat="glow", **k)
    # ---- rooms: floors with holes (pits / water / molten channels) and sunken areas ----
    def room(s, hx, hz, h=8, pits=(), sunken=(), style="hall", skyline=None, wall_base=None, walls=True, tile=None):
        """the arena: floor, four walls. pits = [(x0, z0, x1, z1, kind)] are holes you fall through and die
        (kind: molten / water / abyss / chasm); sunken = [(x0, z0, x1, z1, depth, mat)] are lower floors.
        style picks the wall dress (hall / temple / yard / fort), skyline the distant scenery."""
        s.hx, s.hz, s.h, s.style, s.skyline, s.walls = hx, hz, h, style, skyline, walls
        s.pits = [tuple(p) for p in pits]
        s.sunken = [tuple(p) for p in sunken]
        s.holes = [p[:4] for p in s.pits] + [p[:4] for p in s.sunken]
        deep = any(p[4] == "chasm" for p in s.pits)
        s.wall_base = wall_base if wall_base is not None else (-12 if deep else -4 if s.pits else 0)
        if s.pits: s.raw("void -2.5")
        for (x0, z0, x1, z1) in tiles(minus((-hx - 2, -hz - 2, hx + 2, hz + 2), s.holes), tile):
            s.box(x0, -1, z0, x1, 0, z1)                                         # floor around the holes
        wb = s.wall_base
        if walls:   # (castle / factory maps build their own shell)
            s.box(-hx - 2, wb, -hz - 2, -hx, h, hz + 2); s.box(hx, wb, -hz - 2, hx + 2, h, hz + 2)
            s.box(-hx, wb, -hz - 2, hx, h, -hz); s.box(-hx, wb, hz, hx, h, hz + 2)
            s.clip_walls(-hx, -hz, hx, hz, h)
        if deep:   # the chasm keeps going: unlit rock far below
            s.box(-hx - 2, -60, -hz - 2, -hx, wb, hz + 2, mat="far"); s.box(hx, -60, -hz - 2, hx + 2, wb, hz + 2, mat="far")
            s.box(-hx, -60, -hz - 2, hx, wb, -hz, mat="far"); s.box(-hx, -60, hz, hx, wb, hz + 2, mat="far")
            s.box(-hx, -61, -hz, hx, -60, hz, mat="far")
        for (x0, z0, x1, z1, kind) in s.pits:
            if kind == "chasm": continue
            bot = -3.6 if kind in ("molten", "water") else -14
            if kind in ("molten", "water"):   # a visible surface just below the floor (not solid: in you go, and die).
                s.box(x0, -1.4, z0, x1, -1.2, z1, mat="lava" if kind == "molten" else "water")   # no shaft lining: the
                continue                                                                          # surface hides the shaft
            for (a, b, c, d) in ((x0 - 0.5, z0 - 0.5, x1 + 0.5, z0), (x0 - 0.5, z1, x1 + 0.5, z1 + 0.5), (x0 - 0.5, z0, x0, z1), (x1, z0, x1 + 0.5, z1)):
                s.box(a, bot, b, c, -1, d, accent=True)                          # shaft lining under the floor edge
            s.box(x0, bot - 0.5, z0, x1, bot + 0.6, z1, mat="metal")
            if kind == "molten": s.light((x0 + x1) / 2, -1.0, (z0 + z1) / 2, max(x1 - x0, z1 - z0) * 0.7 + 3, 0.9, fixture=False)
        for (x0, z0, x1, z1, depth, mat) in s.sunken:
            s.box(x0, -depth - 1, z0, x1, -depth, z1, mat=mat)
            for (a, b, c, d) in ((x0 - 0.5, z0 - 0.5, x1 + 0.5, z0), (x0 - 0.5, z1, x1 + 0.5, z1 + 0.5), (x0 - 0.5, z0, x0, z1), (x1, z0, x1 + 0.5, z1)):
                s.box(a, -depth - 1, b, c, -1, d, accent=True)
    def clip_walls(s, x0, z0, x1, z1, h, up=80):
        """invisible clip on top of the outer walls, up out of reach: nobody hooks or jumps out of the map
        (players only: shots, hooks and sight go through)"""
        s.box(x0 - 2, h, z0 - 2, x0, h + up, z1 + 2, mat="clip"); s.box(x1, h, z0 - 2, x1 + 2, h + up, z1 + 2, mat="clip")
        s.box(x0, h, z0 - 2, x1, h + up, z0, mat="clip"); s.box(x0, h, z1, x1, h + up, z1 + 2, mat="clip")
    # ---- the keep-clear registry (REVIEW MAP-5): volumes nothing solid may stand in (the payload cart's sweep along
    # its track, a lane's narrow openings, ...). save() checks every placement against it: generated decor (dress,
    # props, detail, skyline, clutter, cribs, scatter) that lands in one is dropped; anything placed by hand there
    # stops the build with the line and the volume it's in.
    def keep_clear_box(s, x0, y0, z0, x1, y1, z1, why, mirror=False):
        s.__dict__.setdefault("clear_boxes", []).append((min(x0, x1), min(y0, y1), min(z0, z1), max(x0, x1), max(y0, y1), max(z0, z1), why))
        if mirror: s.keep_clear_box(-x1, y0, -z1, -x0, y1, -z0, why)
    @contextlib.contextmanager
    def generated(s):
        """the lines added inside are generated decor (dropped, not an error, where they'd block a keep-clear volume)"""
        before = Counter(s.lines)
        yield
        s.__dict__.setdefault("auto_lines", Counter()).update(Counter(s.lines) - before)
    def cart_clear(s):
        """the payload cart's sweep (its box: 2.4 x 1.8 x 1.5 m, Map::payloadCartBox) along every leg of the track,
        with 10 cm to spare, into the registry"""
        path = [tuple(map(float, l.split()[1:4])) for l in s.lines if l.startswith("path ")]
        for (ax, ay, az), (bx, by, bz) in zip(path, path[1:]):
            lo, hi = min(ay, by) + 0.02, max(ay, by) + 1.6
            if abs(bx - ax) >= abs(bz - az): s.keep_clear_box(min(ax, bx) - 1.3, lo, az - 1.0, max(ax, bx) + 1.3, hi, bz + 1.0, "the payload cart's track")
            else: s.keep_clear_box(ax - 1.0, lo, min(az, bz) - 1.3, bx + 1.0, hi, max(az, bz) + 1.3, "the payload cart's track")
    def check_clear(s):
        """every solid (or visible) box against the keep-clear registry: generated ones in a volume go, hand-placed
        ones are an error"""
        boxes = getattr(s, "clear_boxes", [])
        if not boxes: return
        auto = getattr(s, "auto_lines", Counter())
        kinds = {"box", "accent", "wallbang", "metal", "glow", "trim", "clip"}
        out, errors = [], []
        for l in s.lines:
            w = l.split()
            if w and w[0] in kinds and len(w) == 7:
                b = tuple(map(float, w[1:7]))
                hit = next((z for z in boxes if b[0] < z[3] - 1e-3 and b[3] > z[0] + 1e-3 and b[1] < z[4] - 1e-3 and b[4] > z[1] + 1e-3
                            and b[2] < z[5] - 1e-3 and b[5] > z[2] + 1e-3), None)
                if hit:
                    if auto[l] > 0: auto[l] -= 1; continue
                    errors.append(f"  {l}   is in {hit[6]} ({' '.join(f'{v:g}' for v in hit[:6])})")
            out.append(l)
        if errors: raise SystemExit(f"make_maps.py: {s.name}: placed in a keep-clear volume (move it, or the volume):\n" + "\n".join(errors))
        s.lines = out
    def keep_clear(s, x0, z0, x1, z1, y=2.4):
        """a doorway (and the step in front and behind it): nothing placed later may stand in it"""
        s.__dict__.setdefault("clear_zones", []).append((x0, z0, x1, z1, y))
    def clear_doorways(s):
        """drop solid props / dressing that ended up in a doorway (walls beside it only touch the zone's edge)"""
        zones = getattr(s, "clear_zones", [])
        if not zones: return
        solid = {"box", "accent", "metal", "wallbang", "trim", "glow"}
        out = []
        for l in s.lines:
            w = l.split()
            if w and w[0] in solid and len(w) >= 7:
                x0, y0, z0, x1, y1, z1 = map(float, w[1:7])
                if y1 > 0.3 and any(x0 < b[2] - 1e-3 and x1 > b[0] + 1e-3 and z0 < b[3] - 1e-3 and z1 > b[1] + 1e-3 and y0 < b[4] for b in zones): continue
            out.append(l)
        s.lines = out
    def scale_xz(s, f):
        """spread everything built so far out by f across the ground (heights unchanged): a map made roomier
        without moving every piece by hand. Boxes, stairs, ladders, spawns and lights; lights reach f as far."""
        boxes = {"box", "accent", "wallbang", "metal", "glow", "far", "water", "lava", "trim", "clip", "ladder"}
        g = lambda v: f"{float(v) * f:g}"
        def scaled(l):
            w = l.split()
            if w and w[0] in boxes and len(w) >= 7: w[1], w[3], w[4], w[6] = g(w[1]), g(w[3]), g(w[4]), g(w[6])
            elif w and w[0] == "spawn": w[2], w[4] = g(w[2]), g(w[4])
            elif w and w[0] == "light": w[1], w[3], w[4] = g(w[1]), g(w[3]), g(w[4])
            elif l.startswith("# stairs"): w[2], w[3], w[4], w[5] = g(w[2]), g(w[3]), g(w[4]), g(w[5])
            return " ".join(w) if w and (w[0] in boxes or w[0] in ("spawn", "light") or l.startswith("# stairs")) else l
        s.lines = [scaled(l) for l in s.lines]
        if hasattr(s, "auto_lines"): s.auto_lines = Counter({scaled(l): n for l, n in s.auto_lines.items()})
        s.clear_boxes = [tuple(v * f if i in (0, 2, 3, 5) else v for i, v in enumerate(z[:6])) + (z[6],) for z in getattr(s, "clear_boxes", [])]
        if hasattr(s, "hx"):
            s.hx, s.hz = s.hx * f, s.hz * f
            sc = lambda r: tuple(v * f for v in r[:4]) + tuple(r[4:])
            s.pits, s.sunken, s.holes = [sc(p) for p in s.pits], [sc(p) for p in s.sunken], [sc(p) for p in s.holes]
    def over_hole(s, x, z, r=0.0):
        return any(x0 - r < x < x1 + r and z0 - r < z < z1 + r for (x0, z0, x1, z1) in getattr(s, "holes", []))
    def stairs(s, x0, z0, x1, z1, top, axis, rising, mirror=False, base=0.0, solid=True):
        """steps of 0.5 m from `base` up to `top` along axis ('x' or 'z'), rising toward +/-; solid=False makes
        each step a 1 m slab (a flight in the air, nothing underneath) instead of a block down to the ground"""
        # recorded for quark_tests stairs (every flight is walked, and checked against the paths around it)
        s.lines.append(f"# stairs {x0:g} {z0:g} {x1:g} {z1:g} {base:g} {top:g} {axis} {rising:g} {int(solid)}")
        if mirror: s.lines.append(f"# stairs {-x1:g} {-z1:g} {-x0:g} {-z0:g} {base:g} {top:g} {axis} {-rising:g} {int(solid)}")
        n = max(1, math.ceil((top - base) / 0.5 - 1e-6)); length = (x1 - x0) if axis == "x" else (z1 - z0)   # (every rise <= 0.5 m: the step-up is 0.55)
        for i in range(n):
            a = length * i / n; b = length * (i + 1) / n
            h = base + (top - base) * ((i + 1) if rising > 0 else (n - i)) / n
            y0 = min(base, 0) - (1 if base < 0 else 0) if solid else h - 1
            if axis == "x": s.box(x0 + a, y0, z0, x0 + b, h, z1, mirror=mirror)
            else: s.box(x0, y0, z0 + a, x1, h, z0 + b, mirror=mirror)
    def building(s, x0, z0, x1, z1, h, doors, roof=True, windows=False, lights=True, mirror=False, base=0.0, notch=None):
        """a walled building with doorways and a roof: doors = [(side, center, width)], side in n/s/w/e"""
        t = 0.4
        sides = {"n": (x0, z0, x1, z0 + t, "x"), "s": (x0, z1 - t, x1, z1, "x"), "w": (x0, z0, x0 + t, z1, "z"), "e": (x1 - t, z0, x1, z1, "z")}
        for k, (a, b, c, d, ax) in sides.items():
            ds = [(cc, w, min(2.6, h - 0.4)) for (sd, cc, w) in doors if sd == k]
            if windows and k in ("n", "s"):
                s.windowwall(a, b, c, d, h, 1.1, min(2.3, h - 0.6), every=3.0, width=1.4, mirror=mirror, base=base) if not ds else s.doorwall(a, b, c, d, h, ds, axis=ax, mirror=mirror, base=base)
            else:
                s.doorwall(a, b, c, d, h, ds, axis=ax, mirror=mirror, base=base)
        if roof:
            y = base + h
            notches = (notch if isinstance(notch, list) else [notch]) if notch else []
            for (a, b, c, d) in minus((x0 - 0.3, z0 - 0.3, x1 + 0.3, z1 + 0.3), notches):   # notch(es): open above a ladder / stairs
                s.box(a, y, b, c, y + 0.35, d, accent=True, mirror=mirror)
            for strip in ((x0 - 0.32, z0 - 0.32, x1 + 0.32, z0 - 0.3), (x0 - 0.32, z1 + 0.3, x1 + 0.32, z1 + 0.32)):
                for (a, b, c, d) in minus(strip, notches): s.glow(a, y - 0.1, b, c, y, d, mirror=mirror)
            if lights: s.light((x0 + x1) / 2, y - 0.6, (z0 + z1) / 2, max(x1 - x0, z1 - z0) * 0.8 + 2, 0.8, mirror=mirror)
    def spawn(s, team, x, y, z, yaw, mirror_team=None):
        s.lines.append(f"spawn {team} {x:g} {y:g} {z:g} {yaw:g}")
        if mirror_team: s.lines.append(f"spawn {mirror_team} {-x:g} {y:g} {-z:g} {yaw + 180:g}")
    def raw(s, line): s.lines.append(line)
    # ---- spawn pools (REVIEW MAP-2): every mode a map offers has a spawn for each player a full default-size server
    # (8) puts in its pool: free for all, hide, tag and a tourney's warm-up draw from the "any" spawns, race from the
    # race spawns. save() tops short pools up from open floor (quark_tests spawns checks every pool spawnPlayer uses).
    POOL = 8
    def spawn_spots(s, ys, band=0.6):
        """open standing spots on the floors at heights ys: solid floor under the whole hull, nothing within 0.6 m of
        it up to 2.4 m (pads stay clean), clear of objectives, stairs, ladders, the cart's track, keep-clear volumes
        and other spawns, on this side of any clip (an invisible wall) from the nearest spawn already there, and only
        where players can walk to from the spawns on that floor"""
        kinds = {"box", "accent", "wallbang", "metal", "glow", "clip"}
        solid, avoid, spawns, path, clips = [], [], [], [], []
        for l in s.lines:
            w = l.split()
            if not w: continue
            if w[0] in kinds and len(w) == 7:
                solid.append(tuple(map(float, w[1:7])))
                if w[0] == "clip": clips.append(solid[-1])
            elif w[0] in ("water", "lava", "ladder") and len(w) >= 7: avoid.append(tuple(map(float, w[1:7])))
            elif w[0] in ("site", "hill", "point", "checkpoint") and len(w) >= 7:
                b = tuple(map(float, w[1:7])); avoid.append((b[0] - 2, b[1] - 1, b[2] - 2, b[3] + 2, b[4] + 1, b[5] + 2))
            elif w[0] == "spawn": spawns.append(tuple(map(float, w[2:5])))
            elif w[0] == "path": path.append((float(w[1]), float(w[3])))
            elif l.startswith("# stairs "):
                a = list(map(float, w[2:6])); avoid.append((a[0] - 1.5, -1e9, a[1] - 1.5, a[2] + 1.5, 1e9, a[3] + 1.5))
        avoid += [z[:6] for z in getattr(s, "clear_boxes", [])]
        cell = 4.0
        grid = {}
        for i, b in enumerate(solid):
            for gx in range(int(math.floor(b[0] / cell)), int(math.floor(b[3] / cell)) + 1):
                for gz in range(int(math.floor(b[2] / cell)), int(math.floor(b[5] / cell)) + 1): grid.setdefault((gx, gz), []).append(i)
        def near(x0, z0, x1, z1):
            seen = set()
            for gx in range(int(math.floor(x0 / cell)), int(math.floor(x1 / cell)) + 1):
                for gz in range(int(math.floor(z0 / cell)), int(math.floor(z1 / cell)) + 1):
                    for i in grid.get((gx, gz), ()):
                        if i not in seen: seen.add(i); yield solid[i]
        def hits(q):
            return any(b[0] < q[3] and b[3] > q[0] and b[1] < q[4] and b[4] > q[1] and b[2] < q[5] and b[5] > q[2] for b in near(q[0], q[2], q[3], q[5]))
        def inside(x, y, z):
            return any(b[0] < x < b[3] and b[1] < y < b[4] and b[2] < z < b[5] for b in near(x, z, x, z))
        def floor_at(x, z, y):   # (a spawn may stand a little above its floor: Dojo's are 0.1 m up, on the mat)
            return any(y - 0.15 <= b[4] <= y + 0.01 and b[0] <= x <= b[3] and b[2] <= z <= b[5] for b in near(x, z, x, z))
        def through_clip(x, y, z):   # the line from here to the nearest spawn crosses an invisible wall
            if not spawns: return False
            p = min(spawns, key=lambda q: math.hypot(q[0] - x, q[2] - z))
            for k in range(1, 41):
                t = k / 40; qx, qz = x + (p[0] - x) * t, z + (p[2] - z) * t
                if any(b[0] < qx < b[3] and b[2] < qz < b[5] and b[1] < y + 1 < b[4] for b in clips): return True
            return False
        s._inside = inside
        def seg_d(px, pz, a, b):
            dx, dz = b[0] - a[0], b[1] - a[1]; L = dx * dx + dz * dz
            t = 0 if L == 0 else max(0, min(1, ((px - a[0]) * dx + (pz - a[1]) * dz) / L))
            return math.hypot(px - a[0] - t * dx, pz - a[1] - t * dz)
        xs = [b[0] for b in solid] + [b[3] for b in solid]; zs = [b[2] for b in solid] + [b[5] for b in solid]
        hx, hz = (s.hx, s.hz) if hasattr(s, "hx") else (max(map(abs, xs)), max(map(abs, zs)))
        step = 1.0 if hx * hz < 1500 else 2.0
        def cell_h(x, z, y):   # the floor a hull stands on here, within `band` of height y (None: no room / no floor)
            for t in sorted({b[4] for b in near(x, z, x, z) if b[0] <= x <= b[3] and b[2] <= z <= b[5] and y - band <= b[4] <= y + band}, reverse=True):
                if not hits((x - 0.4, t + 0.01, z - 0.4, x + 0.4, t + 1.8, z + 0.4)): return t
            return None
        out = []
        x0g, z0g = -math.floor(hx) + 1.0, -math.floor(hz) + 1.0
        nxg, nzg = int((hx - 1 - x0g) / step) + 1, int((hz - 1 - z0g) / step) + 1
        for y in ys:
            # flood the floor at about this height from the spawns already on it (walking: steps of 0.55 m, the hull
            # swept between grid points): only spots players can walk to from them (no sealed rooms, no rooftops)
            h, todo = {}, []
            for p in spawns:
                if abs(p[1] - y) > band: continue
                i, k = round((p[0] - x0g) / step), round((p[2] - z0g) / step)
                for (di, dk) in sorted(((a, c) for a in (-1, 0, 1) for c in (-1, 0, 1)), key=lambda q: abs(q[0]) + abs(q[1])):
                    if (i + di, k + dk) in h: break
                    t = cell_h(x0g + (i + di) * step, z0g + (k + dk) * step, y) if 0 <= i + di < nxg and 0 <= k + dk < nzg else None
                    if t is not None: h[(i + di, k + dk)] = t; todo.append((i + di, k + dk)); break
            while todo:
                i, k = todo.pop()
                for (di, dk) in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    c = (i + di, k + dk)
                    if c in h or not (0 <= c[0] < nxg and 0 <= c[1] < nzg): continue
                    xa, za, xb, zb = x0g + i * step, z0g + k * step, x0g + c[0] * step, z0g + c[1] * step
                    t = cell_h(xb, zb, y)
                    if t is None or abs(t - h[(i, k)]) > 0.55: continue
                    top = max(t, h[(i, k)])
                    if hits((min(xa, xb) - 0.4, top + 0.01, min(za, zb) - 0.4, max(xa, xb) + 0.4, top + 1.8, max(za, zb) + 0.4)): continue
                    h[c] = t; todo.append(c)
            for (i, k) in sorted(h):
                x, z = x0g + i * step, z0g + k * step
                if hasattr(s, "hx") and (abs(x) > s.hx - 2.5 or abs(z) > s.hz - 2.5): continue   # (dress() lines the walls)
                ok = all(floor_at(x + dx, z + dz, y) for dx in (-0.4, 0, 0.4) for dz in (-0.4, 0, 0.4)) and \
                     not hits((x - 1.0, y + 0.01, z - 1.0, x + 1.0, y + 2.4, z + 1.0)) and \
                     not any(a[0] < x + 0.5 and a[3] > x - 0.5 and a[1] < y + 2 and a[4] > y and a[2] < z + 0.5 and a[5] > z - 0.5 for a in avoid) and \
                     all(math.hypot(x - p[0], z - p[2]) > 2.5 or abs(y - p[1]) > 3 for p in spawns) and \
                     all(seg_d(x, z, path[n], path[n + 1]) > 3 for n in range(len(path) - 1)) and not through_clip(x, y, z)
                if ok: out.append((x, y, z))
        return out
    def fix_facing(s):
        """REVIEW MAP-16: a spawn faces into the map, not a wall: with something solid within 2 m ahead at eye height
        (what the map tests check), it turns to the nearest of 32 directions with 3 m of open floor ahead (the same
        rule both ways round a point-symmetric map, so mirrored spawns stay mirrored)"""
        solid = [tuple(map(float, l.split()[1:7])) for l in s.lines if l.split()[:1] and l.split()[0] in ("box", "accent", "wallbang", "metal", "glow") and len(l.split()) == 7]
        cell, grid = 4.0, {}
        for i, b in enumerate(solid):
            for gx in range(int(math.floor(b[0] / cell)), int(math.floor(b[3] / cell)) + 1):
                for gz in range(int(math.floor(b[2] / cell)), int(math.floor(b[5] / cell)) + 1): grid.setdefault((gx, gz), []).append(i)
        def inside(x, y, z):
            return any(solid[i][0] <= x <= solid[i][3] and solid[i][1] <= y <= solid[i][4] and solid[i][2] <= z <= solid[i][5] for i in grid.get((int(math.floor(x / cell)), int(math.floor(z / cell))), ()))
        def open_ahead(x, y, z, yaw, far, step):
            dx, dz = -math.sin(math.radians(yaw)), -math.cos(math.radians(yaw))
            d = step
            while d <= far:
                if inside(x + dx * d, y + 1.6, z + dz * d): return False
                d += step
            return True
        out = []
        for l in s.lines:
            w = l.split()
            if w[:1] == ["spawn"] and len(w) >= 6:
                x, y, z, yaw = float(w[2]), float(w[3]), float(w[4]), float(w[5])
                if not open_ahead(x, y, z, yaw, 2.05, 0.05):
                    for k in range(1, 17):
                        turned = next((yaw + sgn * k * 11.25 for sgn in (1, -1) if open_ahead(x, y, z, yaw + sgn * k * 11.25, 3.0, 0.05)), None)
                        if turned is not None:
                            w[5] = f"{(turned + 180) % 360 - 180:g}"; l = " ".join(w); break
            out.append(l)
        s.lines = out
    def face(s, x, y, z):
        """a yaw toward the middle of the map, turned to where there is room to see (MAP-16: not facing a wall):
        of 16 directions, the one with the most open floor ahead (up to 8 m at eye height), leaning to the middle"""
        best, by = -1e9, 0.0
        cx, cz = -x, -z
        L = math.hypot(cx, cz) or 1.0
        for k in range(16):
            a = k * math.pi / 8; dx, dz = math.cos(a), math.sin(a); d = 0.0
            while d < 8 and not s._inside(x + dx * (d + 0.5), y + 1.6, z + dz * (d + 0.5)): d += 0.5
            sc = min(d, 8) + 4 * (dx * cx + dz * cz) / L - (100 if d < 3 else 0)
            if sc > best: best, by = sc, round(math.degrees(math.atan2(-dx, -dz)))
        return by
    def top_up_spawns(s, offered):
        spawns = [l.split() for l in s.lines if l.startswith("spawn ")]
        ranked = any(l.startswith("ranked ") for l in s.lines)   # (ranked maps stay point symmetric: spawns in pairs)
        everything = offered is None
        if everything or "race" in offered:
            have = [w for w in spawns if w[1] == "race"]
            if have and len(have) < s.POOL:
                y = float(have[0][3]); yaw = float(have[0][5]) if len(have[0]) > 5 else 0.0
                cx = sum(float(w[2]) for w in have) / len(have); cz = sum(float(w[4]) for w in have) / len(have)
                pts = [(float(w[2]), float(w[4])) for w in have]
                # the start line: open spots nearest the race spawns already there, 2 m apart (racers spawn together)
                # (never nearer the first checkpoint than the start line: the race's split floors are measured from it)
                cp = next((list(map(float, l.split()[1:7])) for l in s.lines if l.startswith("checkpoint ")), None)
                gap0 = lambda x, z: math.hypot(max(cp[0] - x, 0, x - cp[3]), max(cp[2] - z, 0, z - cp[5])) if cp else 0
                line = min(gap0(float(w[2]), float(w[4])) for w in have)
                spots = sorted((math.hypot(p[0] - cx, p[2] - cz), p[0], p[2]) for p in s.spawn_spots([y]) if math.hypot(p[0] - cx, p[2] - cz) < 12 and gap0(p[0], p[2]) >= line)
                for (_, x, z) in spots:
                    if len(pts) >= s.POOL: break
                    if all(math.hypot(x - a, z - b) >= 2.0 for (a, b) in pts):
                        s.spawn("race", x, y, z, yaw); pts.append((x, z))
        if everything or any(m in offered for m in ("ffa", "hide", "tag", "tourney")):
            have = [tuple(map(float, w[2:5])) for w in spawns if w[1] == "any"]
            if len(have) < s.POOL:
                ys = sorted({round(float(w[3]), 3) for w in spawns}) or [0.0]
                pts = [(p[0], p[1], p[2]) for p in have]
                others = [tuple(map(float, w[2:5])) for w in spawns]
                tops = sorted({float(l.split()[5]) for l in s.lines if l.split()[:1] == ["box"] and len(l.split()) == 7})
                # the floors the spawns stand on; where they haven't the room, the other floors within 2 m of them
                for floors in (ys, [t for t in tops if t not in ys and any(abs(t - y) <= 2 for y in ys)]):
                    if len(have) >= s.POOL or not floors: break
                    every = s.spawn_spots(floors, 0.6 if floors is ys else 2.1)
                    if floors is not ys:   # (other floors: only near the spawns, never across the map from them)
                        every = [q for q in every if min(math.hypot(q[0] - p[0], q[2] - p[2]) for p in pts + others) <= 25]
                    if ranked: every = [p for p in every if any(abs(q[0] + p[0]) < 1e-3 and abs(q[2] + p[2]) < 1e-3 and abs(q[1] - p[1]) < 1e-3 for q in every)]
                    for gap in (6.0, 3.0, 2.0):   # spread 6 m apart; where there is no room for that (Viaduct's start), closer
                        spots = [q for q in every if all(math.dist(q, p) > gap for p in pts)]
                        while len(have) < s.POOL and spots:
                            # the open spot farthest from the pool (and, to start with, from the other spawns): spread out
                            ref = pts if pts else others
                            i = max(range(len(spots)), key=lambda k: (min((math.dist(spots[k], q) for q in ref), default=0), -k))
                            x, y, z = spots[i]
                            picked = [(x, y, z)] + ([q for q in spots if abs(q[0] + x) < 1e-3 and abs(q[2] + z) < 1e-3 and abs(q[1] - y) < 1e-3][:1] if ranked and (x, z) != (0, 0) else [])
                            for (px, py, pz) in picked:
                                s.spawn("any", px, py, pz, s.face(px, py, pz)); have.append((px, py, pz)); pts.append((px, py, pz))
                            spots = [q for q in spots if all(math.dist(q, p) > gap for p in picked)]
    def light(s, x, y, z, radius=9.0, intensity=0.8, fixture=True, mirror=False):
        """baked point light (lights rooms under roofs / overhangs) with a small lamp fixture above it"""
        for (lx, lz) in ((x, z), (-x, -z)) if mirror else ((x, z),):
            s.lines.append(f"light {lx:g} {y:g} {lz:g} {radius:g} {intensity:g}")
            if fixture: s.box(lx - 0.25, y + 0.15, lz - 0.25, lx + 0.25, y + 0.35, lz + 0.25, mat="glow")
    def wallbang(s, x0, y0, z0, x1, y1, z1, mirror=False):
        """dark grey wall that hitscan weapons shoot through (half damage); solid for movement"""
        s.lines.append(f"wallbang {x0:g} {y0:g} {z0:g} {x1:g} {y1:g} {z1:g}")
        if mirror: s.lines.append(f"wallbang {-x1:g} {y0:g} {-z1:g} {-x0:g} {y1:g} {-z0:g}")
    def trim(s, hx, hz, y=0, h=0.25, d=0.12):
        """accent strip along the outer walls, sunk into the wall so its face is flush (purely visual:
        nothing to snag on while sliding along a wall)"""
        s.box(-hx, y, -hz - d, hx, y + h, -hz, accent=True); s.box(-hx, y, hz, hx, y + h, hz + d, accent=True)
        s.box(-hx - d, y, -hz, -hx, y + h, hz, accent=True); s.box(hx, y, -hz, hx + d, y + h, hz, accent=True)
    def pillar(s, x, z, h, r=0.8, mirror=False):
        """column with an accent base and capital"""
        s.box(x - r - 0.2, 0, z - r - 0.2, x + r + 0.2, 0.35, z + r + 0.2, accent=True, mirror=mirror)
        s.box(x - r, 0.35, z - r, x + r, h - 0.35, z + r, mirror=mirror)
        s.box(x - r - 0.2, h - 0.35, z - r - 0.2, x + r + 0.2, h, z + r + 0.2, accent=True, mirror=mirror)
        s.glow(x - r - 0.04, 2.2, z - r - 0.04, x + r + 0.04, 2.32, z + r + 0.04, mirror=mirror)
    def crates(s, x, z, n=2, size=1.2, mirror=False):
        """a little stack of crates (n on the floor, one on top)"""
        for i in range(n): s.box(x + i * size, 0, z, x + (i + 1) * size - 0.05, size, z + size, mirror=mirror)
        s.box(x + size * 0.4, size, z + 0.1, x + size * 1.35, size * 1.8, z + size - 0.1, accent=True, mirror=mirror)
    # ---- structure kit ----
    def catwalk(s, x0, z0, x1, z1, y, rails="z", mirror=False):
        """elevated walkway (0.3 thick) on accent supports, with railings along its long sides"""
        s.box(x0, y - 0.3, z0, x1, y, z1, mat="metal", mirror=mirror)
        for (px, pz) in ((x0, z0), (x1 - 0.4, z0), (x0, z1 - 0.4), (x1 - 0.4, z1 - 0.4)):
            s.box(px, 0, pz, px + 0.4, y - 0.3, pz + 0.4, mat="metal", mirror=mirror)
        if rails != "x":   # glow edge under both long sides
            s.glow(x0, y - 0.32, z0 - 0.02, x1, y - 0.24, z0 + 0.02, mirror=mirror); s.glow(x0, y - 0.32, z1 - 0.02, x1, y - 0.24, z1 + 0.02, mirror=mirror)
        if rails == "z":   # rails on the z = z0 / z1 edges
            s.box(x0, y, z0, x1, y + 0.9, z0 + 0.1, accent=True, mirror=mirror); s.box(x0, y, z1 - 0.1, x1, y + 0.9, z1, accent=True, mirror=mirror)
        elif rails == "x":
            s.box(x0, y, z0, x0 + 0.1, y + 0.9, z1, accent=True, mirror=mirror); s.box(x1 - 0.1, y, z0, x1, y + 0.9, z1, accent=True, mirror=mirror)
    def doorwall(s, x0, z0, x1, z1, h, doors, axis="x", mirror=False, base=0.0):
        """a wall along `axis` with doorways: doors = [(center, width, height)], lintel above each"""
        a0, a1 = (x0, x1) if axis == "x" else (z0, z1)
        cuts = sorted((c - w / 2, c + w / 2, dh) for c, w, dh in doors)
        pos, y0, y1 = a0, base, base + h
        for (c0, c1, dh) in cuts:
            if c0 > pos:
                s.box(pos, y0, z0, c0, y1, z1, mirror=mirror) if axis == "x" else s.box(x0, y0, pos, x1, y1, c0, mirror=mirror)
            s.box(c0, base + dh, z0, c1, y1, z1, mirror=mirror) if axis == "x" else s.box(x0, base + dh, c0, x1, y1, c1, mirror=mirror)  # lintel
            pos = c1
        if pos < a1: s.box(pos, y0, z0, a1, y1, z1, mirror=mirror) if axis == "x" else s.box(x0, y0, pos, x1, y1, a1, mirror=mirror)
    def windowwall(s, x0, z0, x1, z1, h, sill, top, every=3.0, width=1.6, wallbang=False, mirror=False, base=0.0):
        """wall along x with a row of windows between sill and top (wallbang = shoot-through panels)"""
        add = s.wallbang if wallbang else (lambda *a, **k: s.box(*a, **k))
        add(x0, base, z0, x1, base + sill, z1, mirror=mirror); add(x0, base + top, z0, x1, base + h, z1, mirror=mirror)
        x = x0
        while x < x1:
            seg = min(x1, x + every - width)
            add(x, base + sill, z0, seg, base + top, z1, mirror=mirror)
            x += every
    def track(s, pts):
        """railway along a payload path: two rails and sleepers, all sunk flush into the floor"""
        for (ax, az), (bx, bz) in zip(pts, pts[1:]):
            if ax == bx:   # along z
                z0, z1 = min(az, bz) - 0.75, max(az, bz) + 0.75
                for o in (-0.7, 0.7): s.box(ax + o - 0.08, -0.05, z0, ax + o + 0.08, 0, z1, mat="metal")
                z = z0 + 0.4
                while z < z1 - 0.3: s.box(ax - 1.0, -0.06, z - 0.12, ax + 1.0, -0.01, z + 0.12, accent=True); z += 1.4
            else:          # along x
                x0, x1 = min(ax, bx) - 0.75, max(ax, bx) + 0.75
                for o in (-0.7, 0.7): s.box(x0, -0.05, az + o - 0.08, x1, 0, az + o + 0.08, mat="metal")
                x = x0 + 0.4
                while x < x1 - 0.3: s.box(x - 0.12, -0.06, az - 1.0, x + 0.12, -0.01, az + 1.0, accent=True); x += 1.4
    def ladder(s, x, z, y0, y1, face, width=0.9):
        """a climbable ladder 0.12 m off a wall at (x, z) from y0 to y1; face = direction the climber faces
        ('n' = -z, 's' = +z, 'w' = -x, 'e' = +x), i.e. toward the wall. Rails and rungs sit flush against the
        wall (nothing for the climber to snag on); the climb volume reaches a metre above y1 so you come out
        over the top."""
        w = width / 2
        d = {"n": (0, -1), "s": (0, 1), "w": (-1, 0), "e": (1, 0)}[face]
        rx, rz = x + d[0] * 0.09, z + d[1] * 0.09   # centre of the rail / rung layer, against the wall
        if d[0] == 0:
            for sx in (-w, w): s.metal(x + sx - 0.04, y0, rz - 0.03, x + sx + 0.04, y1, rz + 0.03)   # (flush with the top: nothing to trip on stepping off)
            y = y0 + 0.35
            while y < y1: s.box(x - w, y, rz - 0.03, x + w, y + 0.06, rz + 0.03, accent=True); y += 0.4
            z0, z1 = sorted((z, z - d[1] * 0.7))
            s.raw(f"ladder {x - w:g} {y0:g} {z0:g} {x + w:g} {y1 + 1.0:g} {z1:g}")
        else:
            for sz in (-w, w): s.metal(rx - 0.03, y0, z + sz - 0.04, rx + 0.03, y1, z + sz + 0.04)
            y = y0 + 0.35
            while y < y1: s.box(rx - 0.03, y, z - w, rx + 0.03, y + 0.06, z + w, accent=True); y += 0.4
            x0, x1 = sorted((x, x - d[0] * 0.7))
            s.raw(f"ladder {x0:g} {y0:g} {z - w:g} {x1:g} {y1 + 1.0:g} {z + w:g}")
    def tree(s, x, z, size=1.0):
        """trunk and a stepped canopy"""
        s.box(x - 0.3 * size, 0, z - 0.3 * size, x + 0.3 * size, 2.6 * size, z + 0.3 * size, mat="metal")
        for k, (r, y0, y1) in enumerate(((1.8, 2.2, 3.6), (1.4, 3.6, 4.8), (0.8, 4.8, 5.8))):
            s.box(x - r * size, y0 * size, z - r * size, x + r * size, y1 * size, z + r * size, accent=(k % 2 == 0))
    def house(s, x0, z0, x1, z1, h, doors, roof="flat", ladder=None, windows=True):
        """a house: walls with doors / windows and a lamp inside; a flat roof (walkable, with a parapet) or a
        pitched one (stepped, not walkable); ladder = (x, z, face) up the outside onto a flat roof"""
        notch = None
        if ladder:   # cut the roof's overhang and parapet above the ladder so you can climb over the edge
            lx, lz, f = ladder
            notch = {"w": (x1 - 0.05, lz - 0.75, x1 + 0.45, lz + 0.75), "e": (x0 - 0.45, lz - 0.75, x0 + 0.05, lz + 0.75),
                     "n": (lx - 0.75, z1 - 0.05, lx + 0.75, z1 + 0.45), "s": (lx - 0.75, z0 - 0.45, lx + 0.75, z0 + 0.05)}[f]
        s.building(x0, z0, x1, z1, h, doors, roof=True, windows=windows, notch=notch)
        if roof == "flat":
            for (a0, b0, a1, b1) in ((x0 - 0.3, z0 - 0.3, x1 + 0.3, z0), (x0 - 0.3, z1, x1 + 0.3, z1 + 0.3), (x0 - 0.3, z0, x0, z1), (x1, z0, x1 + 0.3, z1)):
                for (a, b, c, d) in minus((a0, b0, a1, b1), [notch] if notch else []):
                    s.box(a, h + 0.35, b, c, h + 0.9, d, accent=True)
        else:
            ax = (x1 - x0) >= (z1 - z0)
            for k in range(1, 4):
                i = k * 0.55 * (min(x1 - x0, z1 - z0) / 2) / 3
                if ax: s.box(x0 - 0.3, h + 0.35 * k, z0 - 0.3 + i, x1 + 0.3, h + 0.35 * (k + 1), z1 + 0.3 - i, accent=True)
                else: s.box(x0 - 0.3 + i, h + 0.35 * k, z0 - 0.3, x1 + 0.3 - i, h + 0.35 * (k + 1), z1 + 0.3, accent=True)
        if ladder: s.ladder(ladder[0], ladder[1], 0, h + 0.35, ladder[2])
    def container(s, x0, z0, x1, z1, h=2.6, mirror=False):
        """shipping container: a box with a ribbed accent band and a lid"""
        s.box(x0, 0, z0, x1, h, z1, mat="metal", mirror=mirror)
        s.box(x0 - 0.05, h * 0.45, z0 - 0.05, x1 + 0.05, h * 0.55, z1 + 0.05, accent=True, mirror=mirror)
        s.box(x0 + 0.1, h, z0 + 0.1, x1 - 0.1, h + 0.15, z1 - 0.1, accent=True, mirror=mirror)
        s.glow(x0 - 0.07, h * 0.2, z0 - 0.07, x1 + 0.07, h * 0.2 + 0.08, z1 + 0.07, mirror=mirror)
    def signal_gantry(s, z, hx, y=7.0, mirror=False):
        """overhead beam across the hall on two columns by the walls (grapple anchor, visual rhythm)"""
        s.box(-hx + 0.6, 0, z - 0.4, -hx + 1.4, y, z + 0.4, mirror=mirror); s.box(hx - 1.4, 0, z - 0.4, hx - 0.6, y, z + 0.4, mirror=mirror)
        s.box(-hx + 0.6, y, z - 0.5, hx - 0.6, y + 0.7, z + 0.5, accent=True, mirror=mirror)
        for x in range(-int(hx) + 6, int(hx) - 4, 6): s.light(x, y - 0.6, z, 9, 0.4, fixture=False)
    # ---- automatic detail pass (runs in save) ----
    def keepouts(s):
        pts = []
        for l in s.lines:
            t = l.split()
            if not t: continue
            if t[0] == "spawn": pts.append((float(t[2]), float(t[4]), 2.2))
            elif t[0] == "path": pts.append((float(t[1]), float(t[3]), 3.0))
            elif t[0] in ("site", "hill", "checkpoint", "point"):
                x0, z0, x1, z1 = float(t[1]), float(t[3]), float(t[4]), float(t[6])
                pts.append(((x0 + x1) / 2, (z0 + z1) / 2, max(abs(x1 - x0), abs(z1 - z0)) / 2 + 1.5))
        # staircases and the ground in front of them: points along the flight, wide enough to keep its ends clear
        for l in s.lines:
            if not l.startswith("# stairs "): continue
            x0, z0, x1, z1 = map(float, l.split()[2:6])
            n = int(max(x1 - x0, z1 - z0) / 1.5) + 1
            for i in range(n + 1):
                f = i / n
                pts.append((x0 + (x1 - x0) * f if x1 - x0 >= z1 - z0 else (x0 + x1) / 2, z0 + (z1 - z0) * f if z1 - z0 > x1 - x0 else (z0 + z1) / 2, min(x1 - x0, z1 - z0) / 2 + 1.8))
        # densify payload paths so debris never lands on the track
        path = [(float(l.split()[1]), float(l.split()[3])) for l in s.lines if l.startswith("path ")]
        for (ax, az), (bx, bz) in zip(path, path[1:]):
            n = int(math.hypot(bx - ax, bz - az) / 2) + 1
            for i in range(n + 1): pts.append((ax + (bx - ax) * i / n, az + (bz - az) * i / n, 3.0))
        return pts
    def clear(s, x, z, r, pts):
        return all(math.hypot(x - px, z - pz) > r + pr for (px, pz, pr) in pts)
    def dress(s, name, stacks=6, lamps=8):
        """architectural detail along the outer walls: trims, corner columns, buttresses with inset panels
        between them, pipes, roof beams, floor seams, wall lamps and a few tidy crate stacks in the bays.
        Everything hugs the walls (keepouts protect spawns, objectives and the payload track). The room's
        style decides which pieces it gets: hall (industrial), temple, yard (outdoors), fort."""
        if not hasattr(s, "hx"): return
        hx, hz, h, style, wb = s.hx, s.hz, s.h, s.style, s.wall_base
        if not getattr(s, "walls", True) and style not in ("castle", "factory"): return   # open maps: no walls to dress
        rnd = random.Random(name)
        pts = s.keepouts()
        if style == "mine": return            # (the mine dresses its own rock: timber sets, strata, lamps)
        if style in ("castle", "factory"):   # their own shells are dressed by the map itself: just the floor seams
            for x in range(-int((hx - 4) // 8) * 8, int(hx - 4) + 1, 8):
                for r in minus((x - 0.06, -hz, x + 0.06, hz), s.holes): s.box(r[0], -0.05, r[1], r[2], 0, r[3], accent=True)
            for z in range(-int((hz - 4) // 8) * 8, int(hz - 4) + 1, 8):
                for r in minus((-hx, z - 0.06, hx, z + 0.06), s.holes): s.box(r[0], -0.05, r[1], r[2], 0, r[3], accent=True)
            return
        s.trim(hx, hz)                                            # base trim
        s.trim(hx, hz, y=h - 0.5, h=0.5, d=0.25)                  # cornice
        if style != "yard": s.trim(hx, hz, y=1.1, h=0.12, d=0.08) # chair rail
        for (y, hh) in ((0.25, 0.1), (h - 0.6, 0.1)):            # glow lines over the base trim and under the cornice
            d = 0.05
            s.glow(-hx, y, -hz - d, hx, y + hh, -hz); s.glow(-hx, y, hz, hx, y + hh, hz + d)
            s.glow(-hx - d, y, -hz, -hx, y + hh, hz); s.glow(hx, y, -hz, hx + d, y + hh, hz)
        for (cx, cz) in ((-hx, -hz), (hx, -hz), (-hx, hz), (hx, hz)):   # corner columns
            x0, x1 = (cx, cx + 1.2) if cx < 0 else (cx - 1.2, cx)
            z0, z1 = (cz, cz + 1.2) if cz < 0 else (cz - 1.2, cz)
            s.box(x0, wb, z0, x1, h + (1.2 if style == "fort" else 0), z1, accent=True)
        if style == "fort":   # battlements along the top of the outer walls
            for along, half, wall in ((True, hx, hz), (False, hz, hx)):
                k = int(half)
                for i in range(-k + 1, k, 2):
                    for side in (-1, 1):
                        w0, w1 = (wall, wall + 2) if side > 0 else (-wall - 2, -wall)
                        if along: s.box(i - 0.5, h, w0, i + 0.5, h + 0.9, w1, accent=True)
                        else: s.box(w0, h, i - 0.5, w1, h + 0.9, i + 0.5, accent=True)
        bays = []   # (x, z, inward normal x, z, along axis) midpoints between buttresses, for panels / lamps / crates
        for along, half, wall in ((True, hx, hz), (False, hz, hx)):
            n = max(2, int(2 * half / 7))
            cs = [-half + i * 2 * half / n for i in range(n + 1)]
            for i in range(1, n):
                c = cs[i]
                for side in (-1, 1):
                    x, z = (c, side * (wall - 0.3)) if along else (side * (wall - 0.3), c)
                    if not s.clear(x, z, 1.0, pts): continue
                    bx0, bz0, bx1, bz1 = (c - 0.5, side * wall - (0.6 if side > 0 else -0.6), c + 0.5, side * wall) if along else \
                                         (side * wall - (0.6 if side > 0 else -0.6), c - 0.5, side * wall, c + 0.5)
                    if style == "yard":   # outdoors: plain posts with a lamp on top instead of buttresses
                        s.box(min(bx0, bx1), wb, min(bz0, bz1), max(bx0, bx1), h + 0.4, max(bz0, bz1), mat="metal")
                        s.glow(min(bx0, bx1) - 0.05, h + 0.4, min(bz0, bz1) - 0.05, max(bx0, bx1) + 0.05, h + 0.6, max(bz0, bz1) + 0.05)
                        continue
                    s.box(min(bx0, bx1), wb, min(bz0, bz1), max(bx0, bx1), h - 0.5, max(bz0, bz1))
                    s.box(min(bx0, bx1) - 0.1, h - 1.4, min(bz0, bz1) - 0.1, max(bx0, bx1) + 0.1, h - 1.1, max(bz0, bz1) + 0.1, accent=True)
            for i in range(n):
                mid, span = (cs[i] + cs[i + 1]) / 2, (cs[i + 1] - cs[i])
                for side in (-1, 1):
                    bays.append((mid, span, side, along, wall))
        # inset panels in every bay (flush, just above the chair rail)
        if style != "yard":
            for (mid, span, side, along, wall) in bays:
                a0, a1, y0, y1 = mid - span / 2 + 1.0, mid + span / 2 - 1.0, 1.6, min(h - 1.8, 5.0)
                if a1 - a0 < 1.5 or y1 - y0 < 1.0: continue
                w0, w1 = (side * wall, side * wall + 0.06) if side > 0 else (side * wall - 0.06, side * wall)  # inside the wall: flush
                if along: s.box(a0, y0, w0, a1, y1, w1, accent=True)
                else: s.box(w0, y0, a0, w1, y1, a1, accent=True)
        long_x = hx >= hz
        if style == "hall":   # pipes along the two long walls
            for side in (-1, 1):
                for y in (h * 0.6, h * 0.6 + 0.45):
                    if y + 0.25 > h - 1.5: continue
                    if long_x: s.box(-hx, y, side * hz - (0.35 if side > 0 else -0.35), hx, y + 0.25, side * hz - (0.05 if side > 0 else -0.05), mat="metal")
                    else: s.box(side * hx - (0.35 if side > 0 else -0.35), y, -hz, side * hx - (0.05 if side > 0 else -0.05), y + 0.25, hz, mat="metal")
        roofed = style in ("hall", "temple") and h >= 8
        if roofed:   # beams across tall rooms: visual rhythm and grapple anchors, with lamps hanging under them
            n = int(2 * (hx if not long_x else hz) / 9)
            span = hx if long_x else hz
            for i in range(1, n + 1):
                c = -(hx if not long_x else hz) + i * 2 * (hx if not long_x else hz) / (n + 1)
                if long_x: s.box(-hx, h - 1.6, c - 0.35, hx, h - 1.0, c + 0.35, accent=True)
                else: s.box(c - 0.35, h - 1.6, -hz, c + 0.35, h - 1.0, hz, accent=True)
                for a in (-span * 0.5, 0, span * 0.5):
                    x, z = (a, c) if long_x else (c, a)
                    s.metal(x - 0.05, h - 2.6, z - 0.05, x + 0.05, h - 1.6, z + 0.05)
                    s.glow(x - 0.45, h - 2.75, z - 0.2, x + 0.45, h - 2.6, z + 0.2)
                    s.light(x, h - 3.0, z, 8, 0.3, fixture=False)
        # emblems on the two end walls: accent backing plate with a glow diamond and bars, high above play
        ew = hx if long_x else hz
        ey0, ey1 = h * 0.5, h * 0.88
        if ey1 - ey0 > 2.5:
            cy, r = (ey0 + ey1) / 2, (ey1 - ey0) / 2
            for side in (-1, 1):
                def ebox(a0, y0, a1, y1, d0, d1, mat):
                    w0, w1 = (side * ew - d1, side * ew - d0) if side > 0 else (side * ew + d0, side * ew + d1)
                    if long_x: s.box(w0, y0, a0, w1, y1, a1, mat=mat)
                    else: s.box(a0, y0, w0, a1, y1, w1, mat=mat)
                ebox(-r * 1.6, ey0, r * 1.6, ey1, 0, 0.08, "accent")
                for i in range(6):                          # stepped diamond outline
                    t = (i + 0.5) / 6; a = r * (1 - t); y = cy + r * t
                    ebox(-a - 0.25, y - 0.12, -a + 0.05, y + 0.12, 0.08, 0.16, "glow"); ebox(a - 0.05, y - 0.12, a + 0.25, y + 0.12, 0.08, 0.16, "glow")
                    y = cy - r * t
                    ebox(-a - 0.25, y - 0.12, -a + 0.05, y + 0.12, 0.08, 0.16, "glow"); ebox(a - 0.05, y - 0.12, a + 0.25, y + 0.12, 0.08, 0.16, "glow")
                ebox(-r * 1.5, cy - 0.08, -r * 0.35, cy + 0.08, 0.08, 0.14, "glow"); ebox(r * 0.35, cy - 0.08, r * 1.5, cy + 0.08, 0.08, 0.14, "glow")
                s.light(side * (ew - 1.5) if long_x else 0, cy, 0 if long_x else side * (ew - 1.5), 7, 0.35, fixture=False)
        # floor seams in both directions (a tiled look), sunk flush, cut around the holes
        for x in range(-int((hx - 4) // 8) * 8, int(hx - 4) + 1, 8):
            for r in minus((x - 0.06, -hz, x + 0.06, hz), s.holes): s.box(r[0], -0.05, r[1], r[2], 0, r[3], accent=True)
        for z in range(-int((hz - 4) // 8) * 8, int(hz - 4) + 1, 8):
            for r in minus((-hx, z - 0.06, hx, z + 0.06), s.holes): s.box(r[0], -0.05, r[1], r[2], 0, r[3], accent=True)
        # wall lamps and tidy crate stacks, placed in mirrored pairs (point symmetry: both sides get the same cover)
        half = [k for k, b in enumerate(bays) if b[2] > 0]
        order = sorted(half, key=lambda k: rnd.random())
        for k in sorted(order[:lamps // 2]):
            mid, span, side, along, wall = bays[k]
            y = min(h - 2.0, 4.2)
            inset = side * (wall - 0.45)
            x, z = (mid, inset) if along else (inset, mid)
            s.light(x, y, z, 8, 0.45, fixture=False, mirror=True)
            if along: s.box(mid - 0.3, y + 0.1, min(inset, side * wall), mid + 0.3, y + 0.35, max(inset, side * wall), mat="glow", mirror=True)
            else: s.box(min(inset, side * wall), y + 0.1, mid - 0.3, max(inset, side * wall), y + 0.35, mid + 0.3, mat="glow", mirror=True)
        for k in order[lamps // 2:]:
            if stacks <= 0: break
            mid, span, side, along, wall = bays[k]
            if span < 5: continue
            inset = side * (wall - 1.3)
            x, z = (mid, inset) if along else (inset, mid)
            if not s.clear(x, z, 2.0, pts) or not s.clear(-x, -z, 2.0, pts): continue
            if s.over_hole(x, z, 2.0) or s.over_hole(-x, -z, 2.0): continue
            size = 1.1
            cx0, cz0 = x - size, z - size / 2
            s.box(cx0, 0, cz0, cx0 + size - 0.04, size, cz0 + size, mirror=True)
            s.box(cx0 + size, 0, cz0, cx0 + 2 * size - 0.04, size, cz0 + size, accent=True, mirror=True)
            s.box(cx0 + size * 0.5, size, cz0 + 0.08, cx0 + size * 1.45, size * 1.8, cz0 + size - 0.08, mirror=True)
            pts.append((x, z, 1.8)); pts.append((-x, -z, 1.8)); stacks -= 2
    def props(s):
        """detail every free-standing cover block on the floor: an accent cap with a small lip and a glow band
        near the base (pairs stay mirrored because every block gets the same treatment)"""
        if not hasattr(s, "hx"): return
        out = []
        spawns = [tuple(map(float, l.split()[2:5])) for l in s.lines if l.startswith("spawn ")]
        flights = [tuple(map(float, l.split()[2:6])) for l in s.lines if l.startswith("# stairs ")]   # steps are not cover blocks:
        for l in s.lines:                                                                             # a capped step is a 0.6 m rise
            t = l.split()
            if not t or t[0] != "box" or len(t) != 7: continue
            x0, y0, z0, x1, y1, z1 = map(float, t[1:])
            w, d, h = x1 - x0, z1 - z0, y1 - y0
            if y0 != 0 or not (0.9 <= h <= 4.5) or w < 1.0 or d < 1.0 or w > 12 or d > 12: continue
            if any(x0 - 0.6 < px < x1 + 0.6 and z0 - 0.6 < pz < z1 + 0.6 for (px, py, pz) in spawns): continue   # spawn pads stay clean
            if any(fx0 - 0.01 <= x0 and x1 <= fx1 + 0.01 and fz0 - 0.01 <= z0 and z1 <= fz1 + 0.01 for (fx0, fz0, fx1, fz1) in flights): continue
            if x0 <= -s.hx + 0.7 or x1 >= s.hx - 0.7 or z0 <= -s.hz + 0.7 or z1 >= s.hz - 0.7: continue   # wall dress
            out.append(f"accent {x0 - 0.06:g} {y1:g} {z0 - 0.06:g} {x1 + 0.06:g} {y1 + 0.1:g} {z1 + 0.06:g}")
            out.append(f"glow {x0 - 0.02:g} 0.3 {z0 - 0.02:g} {x1 + 0.02:g} 0.38 {z1 + 0.02:g}")
        s.lines += out
    def skyline_pass(s, name):
        """distant scenery beyond the walls (unlit 'far' boxes, no collision with play, no lightmap cost),
        generated for one half and mirrored through the centre so symmetric maps stay symmetric"""
        kind = getattr(s, "skyline", None)
        if not kind: return
        R = random.Random(name + "/sky")
        hx, hz, h = s.hx, s.hz, s.h
        def far(x0, y0, z0, x1, y1, z1, mat="far"):   # (always far: lit trims would count as playable space)
            s.box(x0, y0, z0, x1, y1, z1, mat="far", mirror=True)
        def element(cx, cz, out):   # out: unit vector pointing away from the map
            if kind == "city":
                w, d, H = R.uniform(6, 13), R.uniform(6, 12), h + R.uniform(3, 24)
                far(cx - w / 2, -2, cz - d / 2, cx + w / 2, H, cz + d / 2)
                if R.random() < 0.5: far(cx - w / 4, H, cz - d / 4, cx + w / 4, H + R.uniform(3, 8), cz + d / 4)
                if R.random() < 0.35: far(cx - 0.15, H, cz - 0.15, cx + 0.15, H + 6, cz + 0.15, "metal")
                return w
            if kind == "mountains":
                w, H = R.uniform(26, 50), h + R.uniform(8, 30)
                for k in range(4):
                    f = 1 - k * 0.24
                    far(cx - w * f / 2, -2, cz - w * f / 2, cx + w * f / 2, -2 + (H + 2) * (k + 1) / 4, cz + w * f / 2)
                return w * 0.7
            if kind == "stacks":
                if R.random() < 0.45:
                    r, H = R.uniform(1.2, 2.2), h + R.uniform(14, 30)
                    far(cx - r, -2, cz - r, cx + r, H, cz + r)
                    far(cx - r - 0.1, H - 3, cz - r - 0.1, cx + r + 0.1, H - 2.6, cz + r + 0.1, "glow")
                    return 2 * r + 4
                w, d, H = R.uniform(10, 22), R.uniform(8, 14), h + R.uniform(1, 9)
                far(cx - w / 2, -2, cz - d / 2, cx + w / 2, H, cz + d / 2)
                return w
            if kind == "cranes":
                if R.random() < 0.5:
                    H = h + R.uniform(14, 24)
                    far(cx - 1, -2, cz - 1, cx + 1, H, cz + 1)
                    jx, jz = (-out[1], out[0])
                    L = R.uniform(14, 22)
                    far(min(cx, cx + jx * L) - 0.7, H, min(cz, cz + jz * L) - 0.7, max(cx, cx + jx * L) + 0.7, H + 1.4, max(cz, cz + jz * L) + 0.7)
                    far(cx - 0.3, H - 6, cz - 0.3, cx + 0.3, H, cz + 0.3, "glow")
                    return 6
                w, d, H = R.uniform(8, 16), R.uniform(6, 10), h + R.uniform(-2, 6)
                far(cx - w / 2, -2, cz - d / 2, cx + w / 2, H, cz + d / 2)
                return w
            if kind == "pagodas":
                if R.random() < 0.4:
                    r, H = R.uniform(2.5, 4), h + R.uniform(6, 18)
                    tiers = 4
                    for k in range(tiers):
                        y0 = -2 + (H + 2) * k / tiers; y1 = -2 + (H + 2) * (k + 1) / tiers
                        far(cx - r, y0, cz - r, cx + r, y1, cz + r)
                        far(cx - r - 1.6, y1 - 0.4, cz - r - 1.6, cx + r + 1.6, y1, cz + r + 1.6, "accent")
                        r *= 0.8
                    return 12
                w, H = R.uniform(24, 40), h + R.uniform(2, 12)
                for k in range(3):
                    f = 1 - k * 0.3
                    far(cx - w * f / 2, -2, cz - w * f / 2, cx + w * f / 2, -2 + (H + 2) * (k + 1) / 3, cz + w * f / 2)
                return w * 0.7
            if kind == "ruins":
                H = h + R.uniform(-2, 10)
                far(cx - 1.2, -2, cz - 1.2, cx + 1.2, H, cz + 1.2)
                if R.random() < 0.5:
                    jx, jz = (-out[1], out[0])
                    far(min(cx, cx + jx * 7) - 1.2, -2, min(cz, cz + jz * 7) - 1.2, max(cx, cx + jx * 7) + 1.2, H - 2, max(cz, cz + jz * 7) + 1.2)
                    far(min(cx, cx + jx * 7) - 1.4, H - 2, min(cz, cz + jz * 7) - 1.4, max(cx, cx + jx * 7) + 1.4, H - 0.5, max(cz, cz + jz * 7) + 1.4, "accent")
                    return 12
                return 5
            return 10
        dist = {"mountains": (28, 70), "pagodas": (14, 40)}.get(kind, (10, 32))
        for (out, along, half, wall) in (((0, -1), True, hx, hz), ((1, 0), False, hz, hx)):   # north and east; mirrored to south and west
            t = -half - 30
            while t < half + 30:
                d = wall + 2 + R.uniform(*dist)
                cx, cz = (t, -d) if along else (d, t)
                t += element(cx, cz, out) + R.uniform(3, 12)
    def wall_ribs(s, step=1.2, y0=0.4, y1=None, mat="trim"):
        """vertical ribs on the inside faces of the room walls (corrugated fences, ribbed sheds); not solid"""
        hx, hz, h = s.hx, s.hz, s.h
        y1 = h - 0.5 if y1 is None else y1
        x = -hx + step
        while x < hx - 0.5:
            s.box(x - 0.08, y0, -hz, x + 0.08, y1, -hz + 0.05, mat=mat); s.box(x - 0.08, y0, hz - 0.05, x + 0.08, y1, hz, mat=mat); x += step
        z = -hz + step
        while z < hz - 0.5:
            s.box(-hx, y0, z - 0.08, -hx + 0.05, y1, z + 0.08, mat=mat); s.box(hx - 0.05, y0, z - 0.08, hx, y1, z + 0.08, mat=mat); z += step
    def detail_pass(s):
        """architectural finish on every sizeable solid block and wall (>= 2.4 m tall, >= 3 m across): a cap band,
        a skirting band and pilasters every 4 m on each face, all in 'trim' (drawn, not solid: nothing to snag on).
        Faces on the arena boundary are skipped (the room dress handles those, and nobody sees the outside)."""
        hx, hz = getattr(s, "hx", 1e9), getattr(s, "hz", 1e9)
        out = []
        def t(x0, y0, z0, x1, y1, z1): out.append(f"trim {x0:g} {y0:g} {z0:g} {x1:g} {y1:g} {z1:g}")
        for l in list(s.lines):
            tk = l.split()
            if not tk or tk[0] not in ("box", "accent", "metal", "wallbang") or len(tk) != 7: continue
            x0, y0, z0, x1, y1, z1 = map(float, tk[1:])
            w, d, h = x1 - x0, z1 - z0, y1 - y0
            if h < 2.4 or max(w, d) < 3 or min(w, d) < 0.3 or y1 <= 0.5: continue
            if min(w, d) < 1.2 and max(w, d) < 6: continue                     # stair steps, posts
            o, base = 0.04, max(y0, 0.0)
            t(x0 - o, y1 - 0.3, z0 - o, x1 + o, y1 - 0.12, z1 + o)              # cap band
            if base + 0.25 < y1 - 0.3: t(x0 - o, base, z0 - o, x1 + o, base + 0.22, z1 + o)   # skirting
            faces = (("z", z0 - o, z0, x0, x1, z0 > -hz + 0.1), ("z", z1, z1 + o, x0, x1, z1 < hz - 0.1),
                     ("x", x0 - o, x0, z0, z1, x0 > -hx + 0.1), ("x", x1, x1 + o, z0, z1, x1 < hx - 0.1))
            for (ax, f0, f1, a0, a1, inside) in faces:
                if not inside or a1 - a0 < 3: continue
                n = int((a1 - a0) / 4)
                for k in range(1, n + 1):
                    c = a0 + (a1 - a0) * k / (n + 1)
                    yb, yt = base + 0.3, y1 - 0.4
                    if yt - yb < 1.2: continue
                    if ax == "z": t(c - 0.15, yb, f0, c + 0.15, yt, f1)
                    else: t(f0, yb, c - 0.15, f1, yt, c + 0.15)
        s.lines += out
    def clutter(s, x0, z0, x1, z1, step, shapes, seed=0, mirror=False, accent=0.3):
        """low solid props on a jittered grid, skipping anywhere within 1.3 m of an existing brush, 3 m of a spawn or
        3 m of the payload track; mirror=True places each one point-symmetrically too (only where both are free)"""
        with s.generated(): s._clutter(x0, z0, x1, z1, step, shapes, seed, mirror, accent)
    def _clutter(s, x0, z0, x1, z1, step, shapes, seed, mirror, accent):
        rnd = random.Random(seed); solid = []; spawns = []; path = []
        for ln in s.lines:
            w = ln.split()
            if len(w) == 7 and w[0] in ("box", "accent", "metal", "glow", "wallbang", "water", "lava", "ladder"):
                b = list(map(float, w[1:]))
                if b[1] < 2.5 and (b[4] > 0.1 or b[4] < -0.2 or w[0] in ("water", "lava")): solid.append(b)
            elif w and w[0] == "spawn": spawns.append((float(w[2]), float(w[4])))
            elif w and w[0] == "path": path.append((float(w[1]), float(w[3])))
        def seg_d(px, pz, a, b):
            dx, dz = b[0] - a[0], b[1] - a[1]; L = dx * dx + dz * dz
            t = 0 if L == 0 else max(0, min(1, ((px - a[0]) * dx + (pz - a[1]) * dz) / L))
            return math.hypot(px - a[0] - t * dx, pz - a[1] - t * dz)
        def free(cx, cz, hx, hz):
            return (all(not (b[0] - 1.3 < cx + hx and b[3] + 1.3 > cx - hx and b[2] - 1.3 < cz + hz and b[5] + 1.3 > cz - hz) for b in solid)
                    and all((sx - cx) ** 2 + (sz - cz) ** 2 > 9 for (sx, sz) in spawns) and abs(cx) < x1 - 2 and abs(cz) < z1 - 2
                    and all(seg_d(cx, cz, path[i], path[i + 1]) > 3 + max(hx, hz) for i in range(len(path) - 1)))
        x = x0 + step / 2
        while x < x1:
            z = z0 + step / 2
            while z < z1:
                cx, cz = x + rnd.uniform(-1.5, 1.5), z + rnd.uniform(-1.5, 1.5)
                hx, hz, h = rnd.choice(shapes); hx /= 2; hz /= 2
                ok = free(cx, cz, hx, hz) and (not mirror or (abs(cx) > hx + 1.5 or abs(cz) > hz + 1.5) and free(-cx, -cz, hx, hz))
                if ok:
                    s.box(cx - hx, 0, cz - hz, cx + hx, h, cz + hz, accent=rnd.random() < accent, mirror=mirror)
                    solid.append([cx - hx, 0, cz - hz, cx + hx, h, cz + hz])
                    if mirror: solid.append([-cx - hx, 0, -cz - hz, -cx + hx, h, -cz + hz])
                z += step
            x += step
    def cribs(s, cands, size=3.4, h=2.8, count=4, mirror=False):
        """small walled rooms with one doorway (tool cribs, sheds, closets) at the first `count` candidate
        centres where the floor is free: places to hide and to break a chase"""
        with s.generated(): return s._cribs(cands, size, h, count, mirror)
    def _cribs(s, cands, size, h, count, mirror):
        solid = []
        for ln in s.lines:
            w = ln.split()
            if len(w) == 7 and w[0] in ("box", "accent", "metal", "glow", "wallbang", "water", "lava", "ladder"):
                b = list(map(float, w[1:]))
                if b[1] < 3 and (b[4] > 0.1 or b[4] < -0.2): solid.append(b)
            elif w and w[0] in ("spawn", "path"): x, z = float(w[2] if w[0] == "spawn" else w[1]), float(w[4] if w[0] == "spawn" else w[3]); solid.append([x - 1.5, 0, z - 1.5, x + 1.5, 2, z + 1.5])
        r = size / 2; placed = 0
        for (cx, cz, door) in cands:
            pts = [(cx, cz)] + ([(-cx, -cz)] if mirror else [])
            if all(not (b[0] - 1.2 < x + r and b[3] + 1.2 > x - r and b[2] - 1.2 < z + r and b[5] + 1.2 > z - r) for (x, z) in pts for b in solid):
                s.building(cx - r, cz - r, cx + r, cz + r, h, [(door, cz if door in "we" else cx, 1.4)], windows=False, lights=False, mirror=mirror)
                for (x, z) in pts: solid.append([x - r, 0, z - r, x + r, h, z + r])
                placed += 1
                if placed >= count: break
        return placed
    def save(s, name, dress=True):
        MADE.append(name)
        if ARGS.list: return
        # each map plays the mode it's built for, and free for all; Lodestone alone is built for every mode.
        # (any map can still be started in any mode: the menus warn that it may not work)
        mode = next((l.split()[1] for l in s.lines if l.startswith("for ")), None)
        s.lines = [l for l in s.lines if not l.startswith("modes ")]
        if mode and name not in EVERY_MODE: s.lines.insert(3, "modes " + " ".join([mode] + getattr(s, "also", []) + ([] if mode == "ffa" else ["ffa"])))
        s.name = name
        offered = next((l.split()[1:] for l in s.lines if l.startswith("modes ")), None)   # (None: every mode)
        s.top_up_spawns(offered)
        if offered is None or "payload" in offered or "npayload" in offered: s.cart_clear()
        with s.generated():
            if dress: s.props(); s.dress(name); s.detail_pass(); s.skyline_pass(name)
        s.clear_doorways()
        s.check_clear()
        s.fix_facing()
        p = PALETTES.get(name)
        if p:
            p = [tuple(round(v * 0.85, 3) for v in p[0])] + list(p[1:])
            s.lines.insert(4, "palette " + " ".join(f"{k} {c[0]:g} {c[1]:g} {c[2]:g}" for k, c in zip(("base", "accent", "metal", "glow", "sky"), p)))
        os.makedirs(OUT, exist_ok=True)
        with open(os.path.join(OUT, name + ".qmap"), "w", newline="\n") as f: f.write("\n".join(s.lines) + "\n")


def tiles(rects, size):
    """rects cut into pieces at most `size` across (on a grid, so neighbours line up): big maps keep their floor
    as many surfaces, so the bots' routes (and the report's walking distances) follow the floor, not one huge slab"""
    if not size: return list(rects)
    out = []
    for (x0, z0, x1, z1) in rects:
        xs = [x0] + [v for v in range(int(math.floor(x0 / size)) * size + size, int(math.ceil(x1)), size) if x0 < v < x1] + [x1]
        zs = [z0] + [v for v in range(int(math.floor(z0 / size)) * size + size, int(math.ceil(z1)), size) if z0 < v < z1] + [z1]
        for (a, b) in zip(xs, xs[1:]):
            for (c, d) in zip(zs, zs[1:]): out.append((a, c, b, d))
    return out

EVERY_MODE = {"lodestone"}

def minus(rect, holes):
    """rect minus the holes, as a list of rects (grid split, merged along x then across identical rows:
    point-symmetric holes give a point-symmetric result)"""
    x0, z0, x1, z1 = rect
    hs = [(max(a, x0), max(b, z0), min(c, x1), min(d, z1)) for (a, b, c, d) in holes]
    hs = [hh for hh in hs if hh[2] > hh[0] and hh[3] > hh[1]]
    if not hs: return [rect]
    xs = sorted({x0, x1} | {v for hh in hs for v in (hh[0], hh[2])})
    zs = sorted({z0, z1} | {v for hh in hs for v in (hh[1], hh[3])})
    rows = []
    for j in range(len(zs) - 1):
        za, zb = zs[j], zs[j + 1]
        runs, cur = [], None
        for i in range(len(xs) - 1):
            xa, xb = xs[i], xs[i + 1]
            cx, cz = (xa + xb) / 2, (za + zb) / 2
            solid = not any(hh[0] < cx < hh[2] and hh[1] < cz < hh[3] for hh in hs)
            if solid:
                cur = (cur[0], xb) if cur else (xa, xb)
            elif cur:
                runs.append(cur); cur = None
        if cur: runs.append(cur)
        rows.append((za, zb, tuple(runs)))
    out, j = [], 0
    while j < len(rows):
        k = j
        while k + 1 < len(rows) and rows[k + 1][2] == rows[j][2]: k += 1
        for (a, b) in rows[j][2]: out.append((a, rows[j][0], b, rows[k][1]))
        j = k + 1
    return out

