# CANAL: neutral payload down the middle causeway; canals full of water either side (fall in and you're
# out), crossed by three bridges each, with the lock gates as the centrepiece at both ends and canal-side
# houses on the banks.
m = M("Canal", "npayload")
water = []
for sx in (-1, 1):
    a, b = (9, 14) if sx > 0 else (-14, -9)
    for (z0, z1) in ((-44, -21.5), (-18.5, -1.5), (1.5, 18.5), (21.5, 44)): water.append((a, z0, b, z1, "water"))
m.room(22, 42, 10, pits=water, style="yard", skyline="city")
for z in (36, 24, 12, 0, -12, -24, -36): m.raw(f"path 0 0 {z:g}")
m.track([(0, 36), (0, -36)])
m.signal_gantry(0, 22)
for (z0, z1) in ((-21.5, -18.5), (-1.5, 1.5), (18.5, 21.5)):              # bridge railings
    for (a, b) in ((9, 14), (-14, -9)):
        m.box(a, 0, z0 - 0.1, b, 1.0, z0, accent=True); m.box(a, 0, z1, b, 1.0, z1 + 0.1, accent=True)
for side in (-1, 1):                                                       # lock gates: posts, a glowing beam, gate leaves
    z = side * 31
    for (a, b) in ((8.5, 9), (14, 14.5), (-9, -8.5), (-14.5, -14)):
        m.metal(a, -3.6, z - 0.6, b, 6.5, z + 0.6)
    m.box(-14.5, 6.5, z - 0.7, -8.5, 7.2, z + 0.7, accent=True); m.box(8.5, 6.5, z - 0.7, 14.5, 7.2, z + 0.7, accent=True)
    m.glow(-14.5, 6.3, z - 0.75, -8.5, 6.5, z + 0.75); m.glow(8.5, 6.3, z - 0.75, 14.5, 6.5, z + 0.75)
    m.metal(-14, -3.6, z - 0.4, -9, 0.2, z + 0.4); m.metal(9, -3.6, z - 0.4, 14, 0.2, z + 0.4)   # gates: a narrow walkway
    m.light(-11.5, 5.5, z, 7, 0.5, fixture=False); m.light(11.5, 5.5, z, 7, 0.5, fixture=False)
m.building(15, 24, 22, 34, 4.2, [("w", 29, 2.4), ("s", 18.5, 2.2)], windows=True, mirror=True, notch=(14.6, 32.5, 15.05, 33.5))    # canal houses
m.building(15, -14, 22, -4, 3.6, [("w", -9, 2.4), ("n", 18.5, 2.2)], mirror=True, notch=(14.6, -7.0, 15.05, -6.0))
m.ladder(15, 33, 0, 4.55, "e", width=0.8); m.ladder(-15, -33, 0, 4.55, "w", width=0.8)        # up onto the roofs: perches over the canals
m.ladder(15, -6.5, 0, 3.95, "e", width=0.8); m.ladder(-15, 6.5, 0, 3.95, "w", width=0.8)
m.box(-6, 0, 16, -3, 1.6, 20, mirror=True); m.box(3, 0, 16, 6, 1.6, 20, mirror=True)               # causeway cover
m.box(-7, 0, 4, -4, 2.2, 7, mirror=True); m.box(4.5, 0, -1, 7, 1.4, 1, mirror=True)
m.box(-22, 0, -22, -16, 2.5, -16, accent=True, mirror=True); m.stairs(-16, -22, -14.5, -16, 2.5, "x", -1, mirror=True)
for x in (-6, -2, 2, 6): m.spawn("a", x, 0, 40.2, 0, "b")
m.box(-6.6, 0, 37.4, 6.6, 2.6, 37.8, accent=True, mirror=True)               # spawn screens: no sightline down the causeway
m.spawn("any", -18, 0, 0, 90, "any")
# lock-keepers' ladders up the gate posts: the gate beams are a narrow walkway 7 m over the water (a sniper perch
# you can be knocked off)
for (x, z, f) in ((8.5, 31, "e"), (-8.5, 31, "w"), (-8.5, -31, "w"), (8.5, -31, "e")): m.ladder(x, z, 0, 7.2, f, width=0.8)
# humpback footbridges: a high way over each canal between the flat bridges (a second level and a loop)
for flip in (1,):       # one per canal, point symmetric (the other halves of the banks are the canal houses)
    zl, zh = sorted((flip * 4, flip * 9)); m.stairs(7, zl, 9, zh, 2.5, "z", flip, mirror=True)
    dl, dh = sorted((flip * 9, flip * 11)); m.box(7, 2.2, dl, 16, 2.5, dh, mirror=True)
    m.stairs(16, dl, 20, dh, 2.5, "x", -1, mirror=True)                    # down onto the bank, away from the water
    for e in (dl - 0.1, dh): m.box(9, 2.5, e, 14, 3.4, e + 0.1, accent=True, mirror=True)
# boathouse canopies on the banks: shade for the quay, a roofed fight beside the open water
m.box(16, 3.6, -2.5, 22, 3.9, 8.5, accent=True, mirror=True)
for (x, z) in ((16.2, -2.3), (16.2, 8.3)): m.metal(x - 0.2, 0, z - 0.2, x + 0.2, 3.6, z + 0.2, mirror=True)
m.light(19, 3.0, 3.5, 8, 0.7, fixture=False, mirror=True)
# stacked timber on the quays: wooden, so it stops you but not a bullet
m.wallbang(17, 0, 1.5, 18.2, 1.6, 5.5, mirror=True); m.wallbang(19.5, 0, 6, 21, 2.2, 7.2, mirror=True)
m.wallbang(-6, 0, 9, -3, 1.4, 10.2, mirror=True)
m.raw("# setting canal town")
m.save("canal")

# ======================================================================================================
# HARBOR: free for all, the big one. A quay along the north with the sea beyond it (fall in and you're out),
# a moored freighter you can board, three piers and a lighthouse; the yard with containers, a warehouse
# and the dock crane in the south.
m = M("Harbor", "ffa", sun=(0.6, 1.0, 0.15))
m.room(30, 30, 12, pits=[(-30, 22, 30, 30, "water")], style="yard", skyline="cranes")
m.box(-30, 0, 14, 30, 1.2, 22)                                             # quay
m.stairs(-4, 11, 4, 14, 1.2, "z", -1); m.stairs(-24, 11, -18, 14, 1.2, "z", -1); m.stairs(18, 11, 24, 14, 1.2, "z", -1)
for x in (-27, -3, 13, 21): m.box(x - 0.3, 1.2, 21.3, x + 0.3, 2.0, 21.9, accent=True)   # bollards
for (x0, x1) in ((-30, -26.5), (-2, 2), (23, 30)): m.box(x0, -3.6, 22, x1, 1.2, 30)      # piers
# the freighter: hull level with the quay, a bridge cabin you can walk through, mast and funnel
m.metal(-24.5, -3.6, 22.4, -4.5, 1.2, 29.2)
m.metal(-4.5, -3.6, 23.2, -3, 1.2, 28.4); m.metal(-3, -3.6, 24.2, -2.2, 1.2, 27.4)        # bow
m.box(-24.8, 1.2, 22.2, -2.4, 1.6, 22.4, accent=True); m.box(-24.8, 1.2, 29.2, -4.5, 1.6, 29.4, accent=True)  # gunwales
m.building(-22, 23.4, -15.5, 28.4, 2.9, [("s", -18.75, 2.4), ("n", -18.75, 2.0)], windows=True, base=1.2)
m.box(-21, 4.1, 24.4, -16.5, 5.6, 27.4); m.glow(-20.9, 4.9, 24.3, -16.6, 5.2, 27.5)      # wheelhouse
m.box(-13.5, 1.2, 24.7, -11.5, 6.5, 26.9, accent=True); m.glow(-13.6, 5.6, 24.6, -11.4, 5.9, 27.0)  # funnel
m.metal(-8.2, 1.2, 25.6, -7.8, 10, 26); m.metal(-11, 8, 25.7, -5, 8.3, 25.9); m.glow(-8.3, 10, 25.5, -7.7, 10.4, 26.1)
m.container(-11, 23.4, -9, 28.4, h=2.4)
# the lighthouse on the east pier
m.box(24.5, 1.2, 24.5, 28.5, 8, 28.5)
for (a0, b0, a1, b1) in minus((24, 24, 29, 29), [(25.9, 24, 27.1, 24.6)]): m.box(a0, 8, b0, a1, 8.4, b1, accent=True)   # gallery (notched over the ladder)
m.glow(25.6, 8.4, 25.6, 27.4, 10, 27.4); m.box(25.4, 10, 25.4, 27.6, 10.6, 27.6, accent=True)   # the lantern (a walkway round it)
m.light(26.5, 9.2, 23.2, 10, 0.7, fixture=False)
# the yard
for (x0, z0, x1, z1) in ((-26, -10, -20, -4), (8, -24, 14, -18), (-6, -20, 0, -14)): m.container(x0, z0, x1, z1)
m.wallbang(18, 0, -8, 24, 2.6, -2)
m.wallbang(-8, 0, 2, -2, 2.4, 2.4); m.wallbang(4, 0, 4, 10, 2.4, 4.4)
m.crates(-16, -24, 3); m.crates(20, 6, 2); m.crates(-2, 6, 2); m.crates(-24, 4, 1)
m.box(-1, 0, -6, 1, 9, -4, accent=True); m.box(-1, 9, -6, 14, 9.8, -4, accent=True); m.box(13, 6.5, -5.5, 14, 9, -4.5)
m.doorwall(-30, -16.2, -16, -15.8, 4.5, [(-27, 2.4, 2.8), (-22.5, 2.4, 2.8)], axis="x")
m.doorwall(-16.2, -30, -15.8, -16.2, 4.5, [(-23, 2.6, 2.8)], axis="z")
m.box(-30, 4.5, -30, -15.8, 4.8, -15.8, accent=True)
m.stairs(-20, -15.8, -17.6, -11.3, 4.5, "z", -1)
m.light(-26, 3.9, -26, 9, 0.9); m.light(-20, 3.9, -21, 9, 0.9)
m.catwalk(-20, -8, 8, -6.6, 2.8, rails="z")
for (x, z) in ((-22, 18), (22, 18), (6, 18), (-26, -26), (26, -26), (0, -26), (-12, -2), (10, 9), (-18, 8), (25, -14)):
    yaw = math.degrees(math.atan2(x, z))
    m.spawn("any", x, 1.2 if z > 14 else 0, z, round(yaw))
m.spawn("a", -10, 0, -10, 0, "b")
# the transit shed in the south yard: open sides, a roof on columns, pallets inside. Breaks the long yard
# sightlines and gives the south an indoor fight
for x in (2, 8, 14, 20, 26):
    for z in (-29.6, -20.4): m.metal(x - 0.3, 0, z - 0.3, x + 0.3, 6, z + 0.3)
m.box(1.5, 6, -30, 26.5, 6.4, -20, accent=True)
for x in (5, 11, 17, 23): m.glow(x - 0.4, 5.88, -29, x + 0.4, 6, -21); m.light(x, 5.2, -25, 8, 0.7, fixture=False)
m.crates(16, -28, 2); m.crates(21, -24, 1); m.box(3, 0, -27, 5.4, 1.2, -25, accent=True)
# the quay canopy: shade over the quay and the ship's side, posts along the quay edge
for x in range(-28, 29, 8): m.metal(x - 0.25, 1.2, 14.2, x + 0.25, 5.5, 14.7)
m.box(-30, 5.5, 14, 30, 5.9, 19, accent=True); m.glow(-30, 5.38, 14, 30, 5.5, 14.15)
for x in (-20, -4, 12, 26): m.light(x, 4.8, 16.5, 9, 0.6, fixture=False)
# the customs office in the middle: a room you can run through, stairs up the side to its roof (a mid level)
m.building(-14, 6, -6, 12, 3.2, [("w", 9, 2.2), ("e", 9, 2.2), ("s", -10, 2.2)], windows=True)
m.stairs(-14, 3.4, -8, 6, 3.55, "x", -1)                                   # along its north wall (clear of the doors and the quay steps)
# quay clutter that breaks the 60 m quay into stretches: fish crate stacks, net racks, the harbourmaster's hut
for (x, n) in ((-26, 2), (-12, 1), (9, 2), (16, 1)): m.crates(x, 15.2, n, size=1.1)
for x in (-20, 3): m.metal(x, 1.2, 16.8, x + 4, 3.0, 17.0); m.box(x - 0.1, 1.2, 16.6, x + 0.1, 3.2, 17.2, accent=True); m.box(x + 3.9, 1.2, 16.6, x + 4.1, 3.2, 17.2, accent=True)
m.building(-4, 15, 2, 19.5, 2.8, [("s", -1, 2.0), ("e", 17.2, 1.8)], base=1.2, windows=True, lights=True)
# the east yard: two container rows make lanes between the shed and the quay
m.container(18, -16, 24, -12); m.container(18, -16, 24, -12, h=5.2); m.container(10, -12, 15, -9)
m.container(14, 0, 19, 3); m.box(19.5, 0, 0.5, 21.5, 1.4, 2.5)
# a ladder up the lighthouse to its gallery: the classic harbour perch, exposed from every side
m.ladder(26.5, 24.5, 1.2, 8.4, "s", width=0.9)
m.raw("# setting harbour")
m.save("harbor")

# ======================================================================================================
# BASTION: every mode (built for vs). A castle: a thick curtain wall you can walk along the top of, square
# towers jutting out at every corner and halfway along the flanks, a gatehouse at each end (both teams start
# inside one, the portcullis shut behind them), an inner ward wall with gates, and the keep in the middle on
# an island in a moat with four drawbridges. Outside: a water moat and fields under the mountains.
m = M("Bastion", "vs")
moat = [(-10, -10, -1.5, -5, "water"), (1.5, -10, 10, -5, "water"), (-10, 5, -1.5, 10, "water"), (1.5, 5, 10, 10, "water"),
        (-10, -5, -5, -1.5, "water"), (-10, 1.5, -5, 5, "water"), (5, -5, 10, -1.5, "water"), (5, 1.5, 10, 5, "water")]
m.room(30, 30, 7, pits=moat, style="castle", skyline="mountains", walls=False)
W, T, WH = 30, 3.0, 7.0   # curtain wall: inner face at +-30, 3 m thick, wall-walk on top at 7 m
gates = (-3, 3)            # gate passages through the north / south walls
for side in (-1, 1):
    # north / south walls, with the gate passage cut through (portcullis at the outer end)
    for (x0, x1) in ((-W - T, gates[0]), (gates[1], W + T)):
        m.box(x0, -1, side * W if side > 0 else -W - T, x1, WH, side * (W + T) if side > 0 else -W, mirror=False)
    zi, zo = (W, W + T) if side > 0 else (-W - T, -W)
    m.box(gates[0], 4.6, zi, gates[1], WH, zo)                               # over the gate
    for i in range(7): m.metal(gates[0] + 0.4 + i * 0.85, 0, zo - 0.3 if side > 0 else zo, gates[0] + 0.55 + i * 0.85, 4.6, zo if side > 0 else zo + 0.3)   # portcullis bars
    m.metal(gates[0], 2.2, zo - 0.3 if side > 0 else zo, gates[1], 2.35, zo if side > 0 else zo + 0.3)
    m.light(0, 3.6, side * (W + 1.5), 6, 0.6, fixture=False)
    # east / west walls
    xi, xo = (W, W + T) if side > 0 else (-W - T, -W)
    m.box(xi, -1, -W, xo, WH, W)
for side in (-1, 1):   # merlons on the outer edge of the wall-walk, a low lip on the inner edge
    for i in range(-W - 2, W + 3, 2):
        m.box(i - 0.5, WH, side * (W + T) - (0.6 if side > 0 else 0), i + 0.5, WH + 1.1, side * (W + T) + (0 if side > 0 else 0.6), accent=True)
        m.box(side * (W + T) - (0.6 if side > 0 else 0), WH, i - 0.5, side * (W + T) + (0 if side > 0 else 0.6), WH + 1.1, i + 0.5, accent=True)
    m.box(-W, WH, W if side > 0 else -W - 0.25, W, WH + 0.35, W + 0.25 if side > 0 else -W)      # inner lip, on top of the wall
    m.box(W if side > 0 else -W - 0.25, WH, -W, W + 0.25 if side > 0 else -W, WH + 0.35, W)
def tower(cx, cz, half=5.0, top=WH, wall=1.0, rise=3.2, doors=()):
    """a square tower: solid up to the wall-walk, then a walled fighting platform with doorways (doors: sides
    n/s/w/e) and merlons on top, plus a banner and torches on the courtyard side"""
    x0, z0, x1, z1 = cx - half, cz - half, cx + half, cz + half
    m.box(x0, -1, z0, x1, top, z1)
    m.box(x0 - 0.3, top - 0.4, z0 - 0.3, x1 + 0.3, top, z1 + 0.3, accent=True)               # string course
    walls = {"n": (x0, z0, x1, z0 + wall, "x"), "s": (x0, z1 - wall, x1, z1, "x"), "w": (x0, z0, x0 + wall, z1, "z"), "e": (x1 - wall, z0, x1, z1, "z")}
    for k, (a, b, c, d, ax) in walls.items():
        m.doorwall(a, b, c, d, rise, [((a + c) / 2 if ax == "x" else (b + d) / 2, 2.4, 2.4)] if k in doors else [], axis=ax, base=top)
    for i in range(int(x0) + 1, int(x1), 2):
        m.box(i - 0.4, top + rise, z0, i + 0.4, top + rise + 0.9, z0 + wall, accent=True); m.box(i - 0.4, top + rise, z1 - wall, i + 0.4, top + rise + 0.9, z1, accent=True)
    for i in range(int(z0) + 1, int(z1), 2):
        m.box(x0, top + rise, i - 0.4, x0 + wall, top + rise + 0.9, i + 0.4, accent=True); m.box(x1 - wall, top + rise, i - 0.4, x1, top + rise + 0.9, i + 0.4, accent=True)
    m.light(cx, top + 2.4, cz, 7, 0.5, fixture=False)
for (sx, sz) in ((-1, -1), (1, -1), (-1, 1), (1, 1)):                     # corner towers jut out past the walls
    tower(sx * (W + 3), sz * (W + 3), rise=5.0, doors=("w" if sx > 0 else "e", "n" if sz > 0 else "s"))
    # a roof on each corner tower, 12 m up, reached by a ladder inside against the outer wall: the castle's
    # highest perch, overlooking the walls and the fields
    cx, cz = sx * (W + 3), sz * (W + 3); zf = cz + (4.0 if sz > 0 else -4.0)   # inner face of the outer wall
    notch = (cx - 0.6, min(zf, zf - sz * 0.9), cx + 0.6, max(zf, zf - sz * 0.9))
    for (a0, b0, a1, b1) in minus((cx - 4, cz - 4, cx + 4, cz + 4), [notch]): m.box(a0, 11.7, b0, a1, 12.0, b1)
    m.ladder(cx, zf, WH, 12.0, "s" if sz > 0 else "n", width=0.8)
for sx in (-1, 1):                                                         # flank towers halfway along east / west
    tower(sx * (W + 2.5), 0, half=4.0, doors=("n", "s"))
for sz in (-1, 1):                                                         # gatehouse towers either side of each gate
    for gx in (-6.5, 6.5): tower(gx, sz * (W + 3.5), half=3.5, rise=4.4, doors=("e" if gx < 0 else "w",))
# the hoarding: a timber gallery along the inside of the curtain walls, level with the wall-walk (it widens it,
# and roofs a covered ring of courtyard below), on posts
for (a0, b0, a1, b1) in minus((-W, -W, W, W), [(-W + 3, -W + 3, W - 3, W - 3), (gates[0] - 0.5, -W, gates[1] + 0.5, -W + 3), (gates[0] - 0.5, W - 3, gates[1] + 0.5, W),
                                               (-26.5, -W, -11.5, -W + 3), (11.5, W - 3, 26.5, W), (W - 3, 11.5, W, 26.5), (-W, -26.5, -W + 3, -11.5)]):   # (open over the wall stairs)
    m.box(a0, WH - 0.3, b0, a1, WH, b1, accent=True)
for c in range(-24, 25, 8):
    for side in (-1, 1):
        if abs(c) > 4: m.metal(c - 0.2, 0, side * (W - 3) - 0.2, c + 0.2, WH - 0.3, side * (W - 3) + 0.2)
        if abs(c) > 4: m.metal(side * (W - 3) - 0.2, 0, c - 0.2, side * (W - 3) + 0.2, WH - 0.3, c + 0.2)   # (not in front of the bastion stairs)
# a timber breastwork along the gallery's inner edge, in 4 m panels between the posts: archers' cover over the
# courtyard. Planks, so a rifle or sniper shot still goes through (half damage); the gaps let you drop down.
for c in range(-20, 21, 8):
    for side in (-1, 1):
        if abs(c) > 4: m.wallbang(c, WH, side * (W - 3) - 0.1, c + 4, WH + 1.2, side * (W - 3) + 0.1)
        m.wallbang(side * (W - 3) - 0.1, WH, c, side * (W - 3) + 0.1, WH + 1.2, c + 4)
# stairs up to the wall-walk (one flight along each wall, point symmetric)
m.stairs(-26, -29.9, -12, -28, WH, "x", -1, mirror=True)                   # north wall, rising west toward the corner
m.stairs(28, 14, 29.9, 22, WH, "z", 1, base=3.0, mirror=True)              # east wall: on from the raised bastion, rising south
# banners and torches along the inner faces of the curtain walls
for side in (-1, 1):
    for x in (-20, -10, 10, 20):
        zf = side * W - (0.06 if side > 0 else -0.06)
        m.box(x - 1.0, 2.6, min(zf, side * W), x + 1.0, 6.2, max(zf, side * W), accent=True)                # the cloth
        m.glow(x - 1.05, 6.2, min(zf, side * W) - 0.02, x + 1.05, 6.35, max(zf, side * W) + 0.02)           # its pole
        m.glow(x - 0.15, 3.4, min(zf, side * W) - 0.04, x + 0.15, 5.4, max(zf, side * W) + 0.04)            # emblem
    for z in (-20, -10, 10, 20):
        m.glow(side * W - (0.2 if side > 0 else -0.2) - 0.1, 3.0, z - 0.1, side * W - (0.2 if side > 0 else -0.2) + 0.1, 3.4, z + 0.1)   # torch
        m.light(side * (W - 1), 3.2, z, 6, 0.55, fixture=False)
# outside: the water moat round the walls and fields beyond (scenery, out of reach)
for (x0, z0, x1, z1) in ((-60, -60, 60, -38), (-60, 38, 60, 60), (-60, -38, -38, 38), (38, -38, 60, 38)):
    m.box(x0, -1.6, z0, x1, -1.4, z1, mat="far")
for (x0, z0, x1, z1) in ((-38, -38, 38, -33), (-38, 33, 38, 38), (-38, -33, -33, 33), (33, -33, 38, 33)):
    m.box(x0, -3.0, z0, x1, -2.8, z1, mat="water")
# the keep: a tall tower on the island, with a gate and a top you can reach from the inner ward walls
m.box(-2.4, 0, -2.4, 2.4, 6.5, 2.4, accent=True)
for (dx, dz) in ((-1, -1), (1, -1), (-1, 1), (1, 1)):
    x0, x1 = (-2.4, -1.4) if dx < 0 else (1.4, 2.4); z0, z1 = (-2.4, -1.4) if dz < 0 else (1.4, 2.4)
    m.box(x0, 6.5, z0, x1, 8.4, z1)
    m.box(x0 - 0.1, 8.4, z0 - 0.1, x1 + 0.1, 8.7, z1 + 0.1, accent=True)
for (a0, b0, a1, b1) in minus((-2.6, -2.6, 2.6, 2.6), [(-0.6, 2.2, 0.6, 2.6)]): m.box(a0, 6.3, b0, a1, 6.5, b1)   # (notched over the ladder)
m.metal(-0.1, 6.5, -0.1, 0.1, 12, 0.1)
m.glow(0.1, 10.4, -0.05, 2.4, 11.8, 0.05)                                  # banner on the keep
m.box(-2.5, 1.5, -2.5, 2.5, 1.7, 2.5); m.glow(-2.45, 2.0, -2.45, 2.45, 2.1, 2.45)
m.raw("hill -5 0 -5 5 3 5")
m.ladder(0, 2.6, 0, 6.5, "n", width=0.8)                                   # up the keep: its top is a perch over the hill
for (x0, z0, x1, z1, ns) in ((-1.5, -10, 1.5, -5, True), (-1.5, 5, 1.5, 10, True), (-10, -1.5, -5, 1.5, False), (5, -1.5, 10, 1.5, False)):   # drawbridges
    m.metal(x0, -0.1, z0, x1, 0, z1)
    if ns: m.box(x0 - 0.15, 0, z0, x0, 0.9, z1, accent=True); m.box(x1, 0, z0, x1 + 0.15, 0.9, z1, accent=True)
    else: m.box(x0, 0, z0 - 0.15, x1, 0.9, z0, accent=True); m.box(x0, 0, z1, x1, 0.9, z1 + 0.15, accent=True)
# raised bastions on the flanks (west one south of centre, east one north: point symmetric)
