for i in range(5): m.box(-22 - 0.4, 3, -14 + i * 2.2, -22, 3.9, -14 + i * 2.2 + 1.0, accent=True, mirror=True)
m.metal(-26.1, 3, -9.1, -25.9, 9, -8.9, mirror=True); m.glow(-25.9, 7.6, -9.05, -24, 8.8, -8.95, mirror=True)
