for i in range(-13, 14, 2): m.box(i - 0.4, 3.2, 15.75, i + 0.4, 3.9, 16.25, accent=True, mirror=True)
m.stairs(-14, 16.25, -12, 20, 3.2, "z", -1, mirror=True)
