m.metal(-21, 1.0, 21, -20.8, 2.6, 21.2, mirror=True); m.metal(-18.2, 1.0, 23.8, -18, 2.6, 24, mirror=True); m.box(-21.2, 2.6, 21, -17.8, 2.8, 24, accent=True, mirror=True)
