# FURNACE: ranked LASER VAMPIRE. Compact (laser range is 32 m), close corners; the furnace in the middle
# glows through its grates, molten trenches behind the inner walls (bridged in the middle) punish a careless
# pull from the tractor beam. Point symmetric.
m = M("Furnace", "1v1", sun=(0, 1, 0))   # (ranked: the sun overhead, so both halves are lit alike, MAP-17)
m.raw("ranked vampire")
m.room(18, 18, 10, pits=[(-9, 9.5, -2, 11, "molten"), (2, 9.5, 9, 11, "molten"), (-9, -11, -2, -9.5, "molten"), (2, -11, 9, -9.5, "molten")], style="hall", skyline="stacks")
m.box(-3, 0, -3, 3, 4.5, 3, accent=True)
for (a0, b0, a1, b1) in minus((-3.4, -3.4, 3.4, 3.4), [(3.0, 1.5, 3.4, 3.4), (-3.4, -3.4, -3.0, -1.5)]): m.box(a0, 4.5, b0, a1, 5.0, b1)   # the charging deck (notched over the ladders)
m.box(-1.6, 5.0, -1.6, 1.6, 10, 1.6)                                          # the stack (its top: the highest perch)
for y in (7.0, 8.8): m.glow(-1.65, y, -1.65, 1.65, y + 0.15, 1.65)
for (a, b) in ((-3.04, -3.0), (3.0, 3.04)):                                 # grates glowing on all four faces
    for c in (-1.5, -0.5, 0.5, 1.5):
        m.glow(a, 2.2, c - 0.15, b, 3.6, c + 0.15); m.glow(c - 0.15, 2.2, a, c + 0.15, 3.6, b)
m.light(0, 1.2, -3.6, 6, 0.9, fixture=False, mirror=True)
m.box(-1.0, 0.4, 2.9, 1.0, 1.6, 3.1); m.box(-1.0, 0.4, -3.1, 1.0, 1.6, -2.9)
m.box(-5.2, 0, 3.5, -3.8, 0.7, 5.5, mirror=True); m.box(-5.6, 0, -1, -4.2, 0.5, 1, mirror=True)   # coal heaps
m.doorwall(-12, 6.8, 12, 7.2, 4.0, [(-7, 2.4, 2.8), (5, 2.4, 2.8)], axis="x", mirror=True)
m.box(-12, 4.0, 6.8, 12, 4.4, 7.4, accent=True, mirror=True)               # the wall's cap, flush on the court side (a ladder goes up it)
m.box(-18, 0, -4, -14, 2.5, 4, mirror=True); m.stairs(-14, -4, -11, 4, 2.5, "x", -1, mirror=True)
m.box(-18, 2.5, -4.2, -14, 3.4, -4, accent=True, mirror=True); m.box(-18, 2.5, 4, -14, 3.4, 4.2, accent=True, mirror=True)
for (x, z) in ((-10, 13), (10, 13)): m.pillar(x, z, 10.0, r=0.6, mirror=True)
m.box(-6, 0, 12, -3, 1.3, 13, mirror=True); m.box(3, 0, 13.5, 5, 1.6, 15.5, mirror=True)
m.wallbang(-1.5, 0, 12.5, 1.5, 2.4, 12.8, mirror=True)
m.crates(-16, -14, 1, mirror=True)
for x in (-4, 4): m.spawn("a", x, 0, 16, 0, "b")
m.spawn("any", -16, 2.5, 0, 90, "any")
# the stokers' ladders up two opposite sides of the furnace to its charging deck (5 m): a hot perch in the middle
m.ladder(3.0, 2.4, 0, 5.0, "w", width=0.8); m.ladder(-3.0, -2.4, 0, 5.0, "e", width=0.8)
# the side bays behind the inner walls are roofed sheds (where each player starts): indoor fights either side
m.box(-18, 4.0, 7.4, 18, 4.4, 18, mirror=True)
for x in (-12, 0, 12): m.glow(x - 1.2, 3.85, 12, x + 1.2, 4.0, 13, mirror=True); m.light(x, 3.3, 12.5, 8, 0.7, fixture=False, mirror=True)
m.ladder(1.6, 0.6, 5.0, 10.0, "w", width=0.8); m.ladder(-1.6, -0.6, 5.0, 10.0, "e", width=0.8)   # up the stack from the deck
# a ladder up each inner wall onto the side bay's roof (4.4 m): a roof walk over the spawns
m.ladder(-10, 6.8, 0, 4.4, "s", width=0.8); m.ladder(10, -6.8, 0, 4.4, "n", width=0.8)
m.raw("# setting blast furnace")
m.save("furnace")

# DOJO: ranked LASER VAMPIRE, eye to eye. Keep it simple: one open square platform (24 x 24 m, nothing on it)
# in a lava moat, on a mountain top. Both fighters start on it facing each other and bow (no firing for the
# first 5 s); a careless pull off the edge is a swim in the lava. The ring path outside the moat (jump or hook
# back) carries all the decoration: pillars, lanterns, shrines. Point symmetric.
m = M("Dojo", "1v1", sun=(0, 1, 0))   # (ranked: the sun overhead, so both halves are lit alike, MAP-17)
m.raw("ranked vampire")
m.raw("holdfire 5")
P, W = 12, 4.5                                                                 # platform half size, moat width
moat = [(-P - W, -P - W, P + W, -P, "molten"), (-P - W, P, P + W, P + W, "molten"),
        (-P - W, -P, -P, P, "molten"), (P, -P, P + W, P, "molten")]
m.room(23, 23, 3.5, pits=moat, style="temple", skyline="mountains")
m.box(-P, -0.02, -P, P, 0.02, P, mat="trim")                                   # the stone of the platform
m.box(-P + 0.6, 0.02, -P + 0.6, P - 0.6, 0.04, P - 0.6, accent=True)            # the mat (flush: nothing to trip on)
m.box(-1.6, 0.04, -1.6, 1.6, 0.06, 1.6, mat="glow")                            # the centre mark
for (x0, z0, x1, z1) in ((-P, -P, P, -P + 0.3), (-P, P - 0.3, P, P), (-P, -P, -P + 0.3, P), (P - 0.3, -P, P, P)):
    m.box(x0, 0.0, z0, x1, 0.08, z1, mat="glow")                               # glowing edge line: here be lava
m.light(0, 4, 0, 14, 0.5, fixture=False)
for (x, z) in ((-P - W / 2, 0), (P + W / 2, 0), (0, -P - W / 2), (0, P + W / 2)):
    m.light(x, -0.6, z, 12, 0.9, fixture=False)                                # the moat glows up at the walls
# the fight stays on the platform: a running jump clears the 4.5 m moat (a dash-jump 13 m), so an invisible wall
# stands at its far edge, up out of reach (the ring path beyond is scenery)
E = P + W
for (x0, z0, x1, z1) in ((-E - 0.6, -E - 0.6, E + 0.6, -E), (-E - 0.6, E, E + 0.6, E + 0.6), (-E - 0.6, -E, -E, E), (E, -E, E + 0.6, E)):
    m.box(x0, -4, z0, x1, 80, z1, mat="clip")
# outside the moat only: pillars, lanterns, shrines on the ring path
R = P + W + 0.5
for t in (-14, -7, 0, 7, 14):
    m.pillar(-22, t, 6.0, r=0.6, mirror=True); m.pillar(t, -22, 6.0, r=0.6, mirror=True)
for (x, z) in ((-R - 1, -R - 1), (R + 1, R + 1), (-R - 1, R + 1), (R + 1, -R - 1)):
    m.box(x - 0.6, 0, z - 0.6, x + 0.6, 1.0, z + 0.6, accent=True)             # stone lanterns at the corners
    m.glow(x - 0.35, 1.0, z - 0.35, x + 0.35, 1.7, z + 0.35)
    m.box(x - 0.7, 1.7, z - 0.7, x + 0.7, 1.9, z + 0.7, mat="trim")
    m.light(x, 1.4, z, 6, 0.6, fixture=False)
for (x, z) in ((-22.5, 0), (22.5, 0)):
    m.box(x - 0.5, 0, z - 2, x + 0.5, 1.0, z + 2, accent=True)                 # the shrines (against the wall)
    m.glow(x - 0.1, 1.0, z - 1.2, x + 0.1, 3.0, z + 1.2)
for (x, z) in ((0, -22.5), (0, 22.5)):
    m.box(x - 3, 0, z - 0.5, x + 3, 0.5, z + 0.5, mat="trim")                  # bamboo racks
    for k in range(-2, 3): m.metal(x + k * 1.0 - 0.05, 0.5, z - 0.05, x + k * 1.0 + 0.05, 2.6, z + 0.05)
m.spawn("a", -8, 0.1, 0, -90, "b")   # eye to eye across the platform
m.raw("# setting dojo")
m.save("dojo")

# ======================================================================================================
# GANTRY: ranked INSTAGIB. The crane hall: catwalks along both walls, a bridge across the middle over the
# open loading bay (no floor: fall and you're out), two overhead cranes with their cabs and a hanging
# container each. Long sightlines on every level, always a way to break line of sight. Point symmetric.
m = M("Gantry", "ffa", sun=(0, 1, 0))   # (ranked instagib is a free for all; ranked: the sun overhead, MAP-17)
m.raw("ranked instagib")
# (1.13: rebuilt 1.5x longer, 2x wider and 2x taller: 96 x 48 m and 28 m to the roof line; two catwalk tiers,
# cranes 18 m up, and a container yard in the middle so nobody has a shot from spawn to spawn)
GX, GZ, GH = 48, 24, 28
m.room(GX, GZ, GH, pits=[(-5, -14, 5, 14, "water")], sunken=[(-34, -12, -27, 12, 3.0, "metal"), (27, -12, 34, 12, 3.0, "metal")],
       style="hall", skyline="cranes")   # the flooded dock under the bridges; lorry docks sunk at each end
m.lines = [l for l in m.lines if not l.startswith("void ")]; m.raw("void -4.2")   # (the lorry docks' floor at -3 is solid ground:
                                                                                   #  only the flooded dock kills, under its water)
m.metal(-5, -0.3, -14.1, 5, 0, -14); m.metal(-5, -0.3, 14, 5, 0, 14.1)
m.box(-5.1, 0, -14.1, -5, 0.9, 14.1, accent=True, mirror=True)              # bay railings
m.metal(-5, -0.3, -1.5, 5, 0, 1.5)                                            # a gangway across the dock at floor level
for x in (-4, -1, 2): m.box(x, 0, -1.5, x + 0.15, 0.9, -1.35, accent=True, mirror=True)   # its rail posts
# catwalks: the low tier (4 m) the length of both long walls, the high tier (10 m) over its middle
m.catwalk(-42, -23.8, 42, -21.4, 4.0, rails="z", mirror=True)
m.stairs(42, -23.8, 46, -21.4, 4.0, "x", -1, mirror=True); m.stairs(-46, -23.8, -42, -21.4, 4.0, "x", 1, mirror=True)
m.catwalk(-30, -23.8, 30, -21.4, 10.0, rails="z", mirror=True)
m.box(30, 4.0, -23.8, 31, 10.0, -22.6, accent=True, mirror=True)          # low tier -> high tier: a ladder up a pier at each end
m.ladder(31, -23.2, 4.0, 10.0, "w", width=0.8); m.ladder(-31, 23.2, 4.0, 10.0, "e", width=0.8)
# bridges across the hall: the low one over the flooded dock, two high ones between the high tiers
m.catwalk(-1.6, -21.4, 1.6, 21.4, 4.0, rails="x")
m.catwalk(-15.6, -21.4, -12.4, 21.4, 10.0, rails="x", mirror=True)
# the container yard in the middle of each half: stacks you fight around, one high enough to stand on
for (x0, z0, x1, z1, h) in ((-12, -10, -6, -7.6, 2.6), (-12, 6, -6, 8.4, 2.6), (-20, -3, -14, -0.6, 2.6), (-24, 9, -18, 11.4, 2.6),
                            (-26, -13, -23.6, -7, 2.6)):
    m.container(x0, z0, x1, z1, h, mirror=True)
m.container(-20, -3, -14, -0.6, 2.6, mirror=True); m.box(-19.5, 2.6, -2.8, -14.5, 5.2, -0.8, mat="metal", mirror=True)   # a stack of two
m.stairs(-14, -3, -11, -0.6, 2.6, "x", -1, mirror=True)                     # up the side of the stack
for (x0, z0, x1, z1, h) in ((-9, -2, -8, 2, 1.4), (-31, -17, -29, -15, 1.4), (-22, 15, -20, 17, 2.2), (-40, -6, -38, -4, 1.4)):
    m.box(x0, 0, z0, x1, h, z1, mirror=True)
m.wallbang(-10, 0, -0.2, -6, 2.6, 0.2, mirror=True)
m.wallbang(-30, 4.0, -21.4, -29.8, 6.4, -19.8, mirror=True)                 # screens on the low tier
for x in (-34, -20, -8): m.pillar(x, -19, GH, r=0.6, mirror=True)
# cranes: rails along both walls 18 m up, a crane bridge across the hall at each end of the yard, cabs and
# hanging containers; a ladder up each crane's leg from the high tier (the perch over the whole hall, a long fall)
